#[test]
fn root_ambient_agent_pane_sets_root_ambient_agent_context_key() {
    use crate::settings::import::model::ImportedConfigModel;
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(ImportedConfigModel::new);
        let _agent_view_guard = FeatureFlag::AgentView.override_enabled(true);

        let terminal = add_window_with_terminal(&mut app, None);

        terminal.read(&app, |view, ctx| {
            assert!(
                !view
                    .keymap_context(ctx)
                    .set
                    .contains(init::ROOT_AMBIENT_AGENT_PANE_KEY)
            );
        });

        terminal.update(&mut app, |view, ctx| {
            view.ambient_agent_view_model().update(ctx, |model, ctx| {
                model.enter_setup(ctx);
            });
        });

        terminal.read(&app, |view, ctx| {
            assert!(
                view.keymap_context(ctx)
                    .set
                    .contains(init::ROOT_AMBIENT_AGENT_PANE_KEY)
            );
        });

        terminal.update(&mut app, |view, ctx| {
            view.ambient_agent_view_model().update(ctx, |model, _| {
                model.set_has_parent_terminal(true);
            });
        });

        terminal.read(&app, |view, ctx| {
            assert!(
                !view
                    .keymap_context(ctx)
                    .set
                    .contains(init::ROOT_AMBIENT_AGENT_PANE_KEY)
            );
        });
    });
}

