#[test]
fn cmd_enter_from_active_non_empty_agent_view_requires_confirmation() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(ImportedConfigModel::new);
        app.update(|ctx| {
            crate::terminal::init(ctx);
            crate::editor::init(ctx);
        });
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);

        let (window_id, terminal) = add_window_with_id_and_terminal(&mut app, None);

        let original_conversation_id = terminal.update(&mut app, |view, ctx| {
            let (conversation_id, _, _, _) =
                append_exchange_and_handle_event(view, agent_jump_user_query("first"), ctx);
            view.enter_agent_view_for_conversation(
                None,
                AgentViewEntryOrigin::ConversationSelector,
                conversation_id,
                ctx,
            );
            view.focus_terminal(ctx);
            conversation_id
        });

        let keystroke = if cfg!(target_os = "macos") {
            "cmd-enter"
        } else {
            "ctrl-shift-enter"
        };
        let keystroke = warpui::keymap::Keystroke::parse(keystroke).expect("valid keystroke");

        let handled = app
            .dispatch_keystroke(window_id, &[terminal.id()], &keystroke, false)
            .expect("dispatch should succeed");
        assert!(
            handled,
            "new conversation keybinding should be handled from terminal context"
        );

        terminal.read(&app, |view, ctx| {
            assert_eq!(
                view.agent_view_controller()
                    .as_ref(ctx)
                    .agent_view_state()
                    .active_conversation_id(),
                Some(original_conversation_id),
                "first keybinding press should keep the current conversation active"
            );
        });

        let handled = app
            .dispatch_keystroke(window_id, &[terminal.id()], &keystroke, false)
            .expect("dispatch should succeed");
        assert!(
            handled,
            "new conversation keybinding should be handled from terminal context"
        );

        terminal.read(&app, |view, ctx| {
            let new_conversation_id = view
                .agent_view_controller()
                .as_ref(ctx)
                .agent_view_state()
                .active_conversation_id()
                .expect("agent view should be active");
            assert_ne!(
                new_conversation_id, original_conversation_id,
                "second keybinding press should start a new conversation"
            );
        });
    });
}

// --- Cmd-K in the agent view (#418) ---

#[test]
fn cmd_k_in_agent_view_cancels_in_progress_conversation_and_starts_new_one() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        FeatureFlag::AgentView.set_enabled(true);
        // Cancelling the in-progress conversation and starting a new one persists
        // conversation history, which needs GlobalResourceHandlesProvider registered.
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });

        let terminal = add_window_with_terminal(&mut app, None);

        let old_conversation_id = terminal.update(&mut app, |view, ctx| {
            view.agent_view_controller().update(ctx, |controller, ctx| {
                controller
                    .try_enter_agent_view(
                        None,
                        AgentViewEntryOrigin::Input {
                            was_prompt_autodetected: false,
                        },
                        ctx,
                    )
                    .expect("should enter agent view")
            })
        });

        // New conversations always start InProgress.
        terminal.read(&app, |_, ctx| {
            assert_eq!(
                BlocklistAIHistoryModel::as_ref(ctx)
                    .conversation(&old_conversation_id)
                    .map(|c| c.status().clone()),
                Some(ConversationStatus::InProgress)
            );
        });

        // Attach a mock in-flight response stream so cancel_conversation_progress
        // can actually cancel it and flip the status to Cancelled.
        let stream_id = ResponseStreamId::new_for_test();
        terminal.update(&mut app, |view, ctx| {
            // Associate the stream_id with the conversation in the history model so
            // is_processing_response_stream returns true when the controller looks it up.
            BlocklistAIHistoryModel::handle(ctx).update(ctx, |history, ctx| {
                let exchange = exchange_with_inputs(vec![]);
                history
                    .conversation_mut(&old_conversation_id)
                    .expect("conversation should exist")
                    .append_reassigned_exchange(&stream_id, exchange, view.view_id, ctx)
                    .expect("exchange should append");
            });
            let stream = ctx.add_model(|_| ResponseStream::new_for_test(stream_id.clone()));
            view.ai_controller.update(ctx, |controller, ctx| {
                controller.register_mock_stream_for_test(
                    stream_id.clone(),
                    old_conversation_id,
                    stream,
                    ctx,
                );
            });
        });

        // Cmd+K with no long-running command: cancels the old in-progress conversation
        // (stream is cancelled → AfterStreamFinished → Cancelled status) and starts a new one.
        terminal.update(&mut app, |view, ctx| {
            view.clear_buffer_for_testing(ctx);
        });

        terminal.read(&app, |view, ctx| {
            // A new conversation must now be active.
            let new_conversation_id = view
                .agent_view_controller()
                .as_ref(ctx)
                .agent_view_state()
                .active_conversation_id()
                .expect("agent view should still be active after cmd-k");
            assert_ne!(
                new_conversation_id, old_conversation_id,
                "cmd-k must start a new conversation when an in-progress one is active"
            );

            // The old conversation must be Cancelled — the stream was actually cancelled.
            assert_eq!(
                BlocklistAIHistoryModel::as_ref(ctx)
                    .conversation(&old_conversation_id)
                    .map(|c| c.status().clone()),
                Some(ConversationStatus::Cancelled),
                "the old in-progress conversation must be Cancelled after cmd-k"
            );
        });
    })
}

// --- Closing a pane stops its agent (#848) ---

/// Counts the input's `ExecuteAIQuery` (a prompt sent to the agent) and `ExecuteCommand` (a
/// command run in the shell) events: one per queued row actually fired.
fn count_fired_queue_rows(
    app: &mut App,
    terminal: &ViewHandle<TerminalView>,
) -> (Rc<RefCell<usize>>, Rc<RefCell<usize>>) {
    let prompts = Rc::new(RefCell::new(0));
    let commands = Rc::new(RefCell::new(0));
    let input = terminal.read(app, |view, _| view.input().clone());
    let (prompts_sub, commands_sub) = (prompts.clone(), commands.clone());
    app.update(|ctx| {
        ctx.subscribe_to_view(&input, move |_, event: &InputEvent, _| match event {
            InputEvent::ExecuteAIQuery => *prompts_sub.borrow_mut() += 1,
            InputEvent::ExecuteCommand(_) => *commands_sub.borrow_mut() += 1,
            _ => {}
        });
    });
    (prompts, commands)
}

/// The #848 repro at the view level: an agent turn is streaming with a queued prompt and a
/// queued `!` command behind it when the tab is closed. Before the fix nothing on the close
/// path touched the agent: the stream ran on, its turn end drained the queue, the prompt went
/// to the provider and the command ran in the closed tab's shell. Closing must cancel the
/// stream and leave the queue suspended -- no row fires, none is popped into the hidden input
/// -- and undoing the close must not resume anything on its own.
#[test]
fn closing_the_pane_cancels_the_stream_and_suspends_the_queue_until_restored() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        FeatureFlag::AgentView.set_enabled(true);
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(move |_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles.clone())
        });

        let terminal = add_window_with_terminal(&mut app, None);
        let (fired_prompts, fired_commands) = count_fired_queue_rows(&mut app, &terminal);

        let conversation_id = terminal.update(&mut app, |view, ctx| {
            view.agent_view_controller().update(ctx, |controller, ctx| {
                controller
                    .try_enter_agent_view(
                        None,
                        AgentViewEntryOrigin::Input {
                            was_prompt_autodetected: false,
                        },
                        ctx,
                    )
                    .expect("should enter agent view")
            })
        });

        // The streaming turn: an exchange bound to a live (mock) response stream.
        let stream_id = ResponseStreamId::new_for_test();
        terminal.update(&mut app, |view, ctx| {
            BlocklistAIHistoryModel::handle(ctx).update(ctx, |history, ctx| {
                let exchange = exchange_with_inputs(vec![]);
                history
                    .conversation_mut(&conversation_id)
                    .expect("conversation should exist")
                    .append_reassigned_exchange(&stream_id, exchange, view.view_id, ctx)
                    .expect("exchange should append");
            });
            let stream = ctx.add_model(|_| ResponseStream::new_for_test(stream_id.clone()));
            view.ai_controller.update(ctx, |controller, ctx| {
                controller.register_mock_stream_for_test(
                    stream_id.clone(),
                    conversation_id,
                    stream,
                    ctx,
                );
            });
        });

        QueuedQueryModel::handle(&app).update(&mut app, |model, ctx| {
            model.append(
                conversation_id,
                QueuedQuery::new(
                    "please answer queued two".to_owned(),
                    QueuedQueryOrigin::AutoQueueToggle,
                ),
                ctx,
            );
            model.append(
                conversation_id,
                QueuedQuery::new_command(
                    "touch ~/closed-tab-ran".to_owned(),
                    QueuedQueryOrigin::AutoQueueToggle,
                ),
                ctx,
            );
        });
        let queue_texts = |app: &App| {
            QueuedQueryModel::handle(app).read(app, |model, _| {
                model
                    .queue(conversation_id)
                    .iter()
                    .map(|row| row.text().to_owned())
                    .collect::<Vec<_>>()
            })
        };
        let full_queue = vec![
            "please answer queued two".to_owned(),
            "touch ~/closed-tab-ran".to_owned(),
        ];
        let status = |app: &App| {
            BlocklistAIHistoryModel::handle(app).read(app, |history, _| {
                history
                    .conversation(&conversation_id)
                    .map(|c| c.status().clone())
            })
        };
        assert_eq!(status(&app), Some(ConversationStatus::InProgress));

        // Close the tab (what `TerminalPane::detach(HiddenForClose)` does to each view).
        terminal.update(&mut app, |view, ctx| {
            view.suspend_agent_work_for_close(ctx);
        });

        terminal.read(&app, |view, ctx| {
            assert!(view.is_suspended_for_close());
            assert!(
                !view
                    .ai_controller()
                    .as_ref(ctx)
                    .has_active_stream_for_conversation(conversation_id, ctx),
                "closing the pane must cancel the in-flight request"
            );
            assert_eq!(
                view.input().as_ref(ctx).buffer_text(ctx),
                "",
                "the cancel must not pop a queued row into the closed pane's input"
            );
        });
        assert_eq!(status(&app), Some(ConversationStatus::Cancelled));
        assert_eq!(
            queue_texts(&app),
            full_queue,
            "the queue survives the close"
        );

        // Everything that could drain the queue while the pane sits in the undo stack: a turn
        // end, and a previously dispatched queued command finishing.
        terminal.update(&mut app, |view, ctx| {
            view.drain_queued_prompts(conversation_id, FinishReason::Complete, ctx);
            QueuedQueryModel::handle(ctx).update(ctx, |model, _| {
                model.arm_command_in_flight(conversation_id);
            });
            view.on_queued_command_finished(ctx);
        });
        assert_eq!(
            *fired_prompts.borrow(),
            0,
            "no prompt is sent from a closed pane"
        );
        assert_eq!(
            *fired_commands.borrow(),
            0,
            "no command runs in a closed pane"
        );
        assert_eq!(queue_texts(&app), full_queue);

        // Undo the close: nothing resumes by itself.
        terminal.update(&mut app, |view, ctx| view.resume_after_close_undone(ctx));
        terminal.read(&app, |view, ctx| {
            assert!(!view.is_suspended_for_close());
            assert!(
                !view
                    .ai_controller()
                    .as_ref(ctx)
                    .has_active_stream_for_conversation(conversation_id, ctx)
            );
        });
        assert_eq!(status(&app), Some(ConversationStatus::Cancelled));
        assert_eq!(queue_texts(&app), full_queue);
        assert_eq!(*fired_prompts.borrow(), 0);
        assert_eq!(*fired_commands.borrow(), 0);

        // Once restored the queue behaves normally again: the next clean turn end takes the head.
        terminal.update(&mut app, |view, ctx| {
            view.drain_queued_prompts(conversation_id, FinishReason::Complete, ctx);
        });
        assert_eq!(queue_texts(&app), vec!["touch ~/closed-tab-ran".to_owned()]);
    })
}

/// While a pane is closed, a one-shot "send after this turn" follow-up must be treated as
/// cancelled rather than sent, whatever the turn's own finish reason (#848).
#[test]
fn closed_pane_runs_conversation_finished_callbacks_as_cancelled() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);

        let seen = Rc::new(RefCell::new(Vec::new()));
        terminal.update(&mut app, |view, ctx| {
            let seen = seen.clone();
            view.conversation_completed_callbacks.push(Box::new(
                move |_: &mut TerminalView,
                      reason: FinishReason,
                      _: &mut ViewContext<TerminalView>| {
                    seen.borrow_mut().push(reason)
                },
            ));
            view.suspend_agent_work_for_close(ctx);
            view.fire_conversation_finished_callbacks(FinishReason::Complete, ctx);
        });
        assert_eq!(*seen.borrow(), vec![FinishReason::Cancelled]);
    })
}

/// Starts a non-empty, in-progress conversation that is the view's active one, with no
/// in-flight stream (so stopping it sets `Cancelled` directly).
fn start_running_conversation_for_close(
    view: &mut TerminalView,
    ctx: &mut ViewContext<TerminalView>,
) -> AIConversationId {
    let terminal_view_id = view.view_id;
    BlocklistAIHistoryModel::handle(ctx).update(ctx, |history, ctx| {
        let id = history.start_new_conversation(terminal_view_id, false, false, ctx);
        history.set_active_conversation_id(id, terminal_view_id, ctx);
        history
            .conversation_mut(&id)
            .expect("conversation should exist")
            .append_reassigned_exchange(
                &ResponseStreamId::new_for_test(),
                exchange_with_inputs(vec![]),
                terminal_view_id,
                ctx,
            )
            .expect("exchange should append");
        history.update_conversation_status(
            terminal_view_id,
            id,
            ConversationStatus::InProgress,
            ctx,
        );
        id
    })
}

/// Counts the ETX (Ctrl-C) writes and `DiscardPendingCommandWrites` requests `terminal` sends
/// toward its PTY.
fn count_close_pty_effects(
    app: &mut App,
    terminal: &ViewHandle<TerminalView>,
) -> (Rc<RefCell<usize>>, Rc<RefCell<usize>>) {
    let etx = Rc::new(RefCell::new(0));
    let discards = Rc::new(RefCell::new(0));
    let (etx_sub, discards_sub) = (etx.clone(), discards.clone());
    app.update(|ctx| {
        ctx.subscribe_to_view(terminal, move |_, event, _| match event {
            Event::WriteBytesToPty { bytes } if bytes.contains(&C0::ETX) => {
                *etx_sub.borrow_mut() += 1;
            }
            Event::DiscardPendingCommandWrites => *discards_sub.borrow_mut() += 1,
            _ => {}
        });
    });
    (etx, discards)
}

fn register_global_resource_handles(app: &mut App) {
    let global_resource_handles = crate::GlobalResourceHandles::mock(app);
    app.add_singleton_model(move |_| {
        crate::GlobalResourceHandlesProvider::new(global_resource_handles.clone())
    });
}

/// Builds a close-test terminal whose running conversation's agent requested the active
/// block's command. `executing` starts the command; otherwise the block is still at the
/// prompt, i.e. the agent wrote the command but the shell has not reached preexec.
fn terminal_with_agent_command(
    app: &mut App,
    executing: bool,
) -> (ViewHandle<TerminalView>, AIConversationId) {
    initialize_app_for_terminal_view(app);
    register_global_resource_handles(app);
    let terminal = add_window_with_terminal(app, None);
    let conversation_id = terminal.update(app, |view, ctx| {
        let conversation_id = start_running_conversation_for_close(view, ctx);
        if executing {
            view.model
                .lock()
                .simulate_long_running_block("cargo build", "compiling");
        }
        view.model
            .lock()
            .block_list_mut()
            .active_block_mut()
            .set_agent_interaction_mode_for_requested_command(
                AIAgentActionId::from("requested-command".to_owned()),
                None,
                conversation_id,
            );
        conversation_id
    });
    (terminal, conversation_id)
}

/// #848: closing a pane interrupts the command its agent is running...
#[test]
fn closing_the_pane_interrupts_the_agents_running_command() {
    App::test((), |mut app| async move {
        let (terminal, _) = terminal_with_agent_command(&mut app, true);
        let (etx, discards) = count_close_pty_effects(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| view.suspend_agent_work_for_close(ctx));

        assert_eq!(
            *etx.borrow(),
            1,
            "the agent's command is interrupted on close"
        );
        assert_eq!(*discards.borrow(), 1);
    })
}

/// ...including one the agent wrote that the shell has not started yet (before preexec): the
/// line is interrupted and a copy still parked in the PTY write queue is dropped.
#[test]
fn closing_the_pane_interrupts_an_agent_command_not_yet_started() {
    App::test((), |mut app| async move {
        let (terminal, _) = terminal_with_agent_command(&mut app, false);
        let (etx, discards) = count_close_pty_effects(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| view.suspend_agent_work_for_close(ctx));

        assert_eq!(*etx.borrow(), 1);
        assert_eq!(*discards.borrow(), 1, "the parked command write is dropped");
    })
}

/// ...but never a command the user started themselves (`npm run dev` launched while the agent
/// streams), even though the conversation is the view's active one -- which a manual Ctrl-C
/// stop would interrupt.
#[test]
fn closing_the_pane_does_not_interrupt_the_users_own_command() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        register_global_resource_handles(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let (etx, discards) = count_close_pty_effects(&mut app, &terminal);

        let conversation_id = terminal.update(&mut app, |view, ctx| {
            let conversation_id = start_running_conversation_for_close(view, ctx);
            view.model
                .lock()
                .simulate_long_running_block("npm run dev", "listening on :3000");
            conversation_id
        });
        terminal.update(&mut app, |view, ctx| view.suspend_agent_work_for_close(ctx));

        assert_eq!(*etx.borrow(), 0, "the user's own command keeps running");
        assert_eq!(*discards.borrow(), 0);
        terminal.read(&app, |_, ctx| {
            assert_eq!(
                BlocklistAIHistoryModel::as_ref(ctx)
                    .conversation(&conversation_id)
                    .map(|c| c.status().clone()),
                Some(ConversationStatus::Cancelled),
                "the agent is still stopped"
            );
        });
    })
}

/// ...nor a user command the user tagged the agent into: it carries the conversation's agent
/// metadata, but the agent never requested it.
#[test]
fn closing_the_pane_does_not_interrupt_a_user_command_the_agent_was_tagged_into() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        register_global_resource_handles(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let (etx, _) = count_close_pty_effects(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| {
            let conversation_id = start_running_conversation_for_close(view, ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh build-box", "$ ");
            let task_id = TaskId::new("tagged-in".to_owned());
            view.model
                .lock()
                .block_list_mut()
                .active_block_mut()
                .set_agent_interaction_mode_for_agent_monitored_command(&task_id, conversation_id)
                .expect("a user command can be tagged in");
        });
        terminal.update(&mut app, |view, ctx| view.suspend_agent_work_for_close(ctx));

        assert_eq!(
            *etx.borrow(),
            0,
            "the user's tagged-in command keeps running"
        );
    })
}

/// ...and never the idle prompt, where a Ctrl-C would wipe the user's half-typed line.
#[test]
fn closing_the_pane_does_not_interrupt_the_idle_prompt() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        register_global_resource_handles(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let (etx, _) = count_close_pty_effects(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| {
            start_running_conversation_for_close(view, ctx);
            view.input().update(ctx, |input, ctx| {
                input.replace_buffer_content("git commit -m 'half typ", ctx);
            });
        });
        terminal.update(&mut app, |view, ctx| view.suspend_agent_work_for_close(ctx));

        assert_eq!(*etx.borrow(), 0, "the prompt is left alone");
    })
}

/// Builds an agent-monitored long-running block for `conversation_id` that the user has taken
/// over (`Manual`), i.e. one whose completion auto-resumes the conversation. Returns its id.
fn manual_takeover_lrc_block(
    view: &mut TerminalView,
    conversation_id: AIConversationId,
    command: &str,
) -> BlockId {
    view.model
        .lock()
        .simulate_long_running_block(command, "running");
    let task_id = TaskId::new(format!("cli-subagent-{command}"));
    let mut model = view.model.lock();
    let active_block = model.block_list_mut().active_block_mut();
    active_block.set_agent_interaction_mode_for_requested_command(
        AIAgentActionId::from(format!("requested-{command}")),
        Some(task_id.clone()),
        conversation_id,
    );
    active_block
        .set_agent_interaction_mode_for_agent_monitored_command(&task_id, conversation_id)
        .expect("command should become agent monitored");
    active_block
        .take_over_control_for_user(UserTakeOverReason::Manual)
        .expect("user takeover should succeed");
    active_block.id().clone()
}

/// #848: a long-running agent command the user took over (`Manual`) is not stopped by the
/// close -- it is the user's command now, and its conversation is no longer running -- but when
/// it exits in the closed tab it must not auto-resume the conversation and send a request; nor
/// is that resume owed once the tab is restored. Once restored, the same kind of completion
/// resumes again, which shows the first assertion is not vacuous.
#[test]
fn completed_user_controlled_lrc_does_not_resume_in_a_closed_pane() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view_guard = FeatureFlag::AgentView.override_enabled(true);
        register_global_resource_handles(&mut app);

        let terminal = add_window_with_terminal(&mut app, None);
        let has_stream = |app: &App, conversation_id: AIConversationId| {
            terminal.read(app, |view, ctx| {
                view.ai_controller
                    .as_ref(ctx)
                    .has_active_stream_for_conversation(conversation_id, ctx)
            })
        };

        let (conversation_id, block_id) = terminal.update(&mut app, |view, ctx| {
            let conversation_id = BlocklistAIHistoryModel::handle(ctx)
                .update(ctx, |history, ctx| {
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });
            let block_id = manual_takeover_lrc_block(view, conversation_id, "sleep 20");
            (conversation_id, block_id)
        });

        terminal.update(&mut app, |view, ctx| view.suspend_agent_work_for_close(ctx));
        terminal.update(&mut app, |view, ctx| {
            view.on_user_block_completed(&block_id, ctx)
        });
        assert!(
            !has_stream(&app, conversation_id),
            "a closed pane must not resume the conversation"
        );

        terminal.update(&mut app, |view, ctx| view.resume_after_close_undone(ctx));
        assert!(
            !has_stream(&app, conversation_id),
            "restoring the pane must not deliver the skipped resume"
        );

        // Control: in the restored pane, a completed take-over resumes as usual.
        let second_block_id = terminal.update(&mut app, |view, _| {
            view.model.lock().finish_block();
            manual_takeover_lrc_block(view, conversation_id, "sleep 30")
        });
        terminal.update(&mut app, |view, ctx| {
            view.on_user_block_completed(&second_block_id, ctx)
        });
        assert!(has_stream(&app, conversation_id));
    })
}

/// A conversation stopped mid-batch: a command awaiting approval, behind an earlier action of
/// the same batch that already succeeded -- the shape in which cancelling the pending action
/// makes the controller's `FinishedAction` subscriber send the batch's results as a follow-up.
struct MidBatch {
    terminal: ViewHandle<TerminalView>,
    conversation_id: AIConversationId,
    action_model: ModelHandle<BlocklistAIActionModel>,
    blocked_action_id: AIAgentActionId,
    sent_requests: Rc<RefCell<usize>>,
}

async fn mid_batch(app: &mut App) -> MidBatch {
    use crate::ai::agent::{
        AIAgentAction, AIAgentActionResult, AIAgentActionResultType, AIAgentActionType,
        TransferShellCommandControlToUserResult,
    };

    initialize_app_for_terminal_view(app);
    register_global_resource_handles(app);
    let terminal = add_window_with_terminal(app, None);

    let sent_requests = Rc::new(RefCell::new(0));
    let controller = terminal.read(app, |view, _| view.ai_controller().clone());
    let sent_requests_sub = sent_requests.clone();
    app.update(|ctx| {
        ctx.subscribe_to_model(&controller, move |_, event, _| {
            if matches!(event, BlocklistAIControllerEvent::SentRequest { .. }) {
                *sent_requests_sub.borrow_mut() += 1;
            }
        });
    });

    let conversation_id = terminal.update(app, |view, ctx| {
        start_running_conversation_for_close(view, ctx)
    });
    let action_model = terminal.read(app, |view, _| view.ai_action_model.clone());
    // The batch's actions belong to the conversation's own root task. The follow-up that carries
    // their results is added to the task the results name, and since #1945 a request whose task
    // does not exist is refused before `SentRequest` ("Not sending the request: no exchange could
    // be added ... NoActiveTask"). With the made-up task id this fixture had before, the
    // positive control below could send nothing, and the two "sends nothing" tests could not
    // fail.
    let task_id = BlocklistAIHistoryModel::handle(app).read(app, |history, _| {
        history
            .conversation(&conversation_id)
            .expect("conversation should exist")
            .get_root_task_id()
            .clone()
    });

    let blocked_action_id = AIAgentActionId::from("awaiting-approval".to_owned());
    action_model.update(app, |action_model, ctx| {
        action_model.queue_action_for_test(
            AIAgentAction {
                id: blocked_action_id.clone(),
                task_id: task_id.clone(),
                action: AIAgentActionType::RequestCommandOutput {
                    command: "free -h".to_owned(),
                    is_read_only: None,
                    is_risky: None,
                    rationale: None,
                    uses_pager: None,
                    wait_until_completion: true,
                    citations: vec![],
                },
                requires_result: false,
            },
            conversation_id,
            ctx,
        );
    });
    for _ in 0..64 {
        let is_blocked = action_model.read(app, |action_model, _| {
            action_model
                .get_action_status(&blocked_action_id)
                .is_some_and(|status| status.is_blocked())
        });
        if is_blocked {
            break;
        }
        futures_lite::future::yield_now().await;
    }
    action_model.update(app, |action_model, _| {
        assert!(
            action_model
                .get_action_status(&blocked_action_id)
                .is_some_and(|status| status.is_blocked()),
            "precondition: the command is blocked on approval"
        );
        action_model.push_finished_action_result_for_test(
            conversation_id,
            AIAgentActionResult {
                id: AIAgentActionId::from("already-ran".to_owned()),
                task_id: task_id.clone(),
                result: AIAgentActionResultType::TransferShellCommandControlToUser(
                    TransferShellCommandControlToUserResult::Snapshot {
                        block_id: BlockId::default(),
                        grid_contents: "done".to_owned(),
                        cursor: "<|cursor|>".to_owned(),
                        is_alt_screen_active: false,
                        is_preempted: false,
                    },
                ),
            },
        );
    });

    MidBatch {
        terminal,
        conversation_id,
        action_model,
        blocked_action_id,
        sent_requests,
    }
}

impl MidBatch {
    /// What the card's Reject button does to the pending command. Since #1942 (owner decision
    /// 2026-11-09) a Reject has its own reason: it is not a stop, and with an earlier result of
    /// the step finished it sends the step's results at once. `ManuallyCancelled`, which this
    /// helper used to pass (what a Reject sent before the decision), is now a user stop and
    /// sends nothing in any pane, so it could no longer serve as the positive control.
    fn cancel_blocked_action(&self, app: &mut App) {
        let (conversation_id, blocked_action_id) =
            (self.conversation_id, self.blocked_action_id.clone());
        self.action_model.update(app, |action_model, ctx| {
            action_model.cancel_action_with_id(
                conversation_id,
                &blocked_action_id,
                CancellationReason::Rejected,
                ctx,
            );
        });
    }

    fn status(&self, app: &App) -> Option<ConversationStatus> {
        BlocklistAIHistoryModel::handle(app).read(app, |history, _| {
            history
                .conversation(&self.conversation_id)
                .map(|c| c.status().clone())
        })
    }
}

async fn let_subscribers_run() {
    for _ in 0..16 {
        futures_lite::future::yield_now().await;
    }
}

/// Positive control for the mid-batch tests below: in an open pane, rejecting the pending
/// action of a batch whose earlier action succeeded sends the batch's results as a follow-up
/// (#1942, second part: a Reject is not a stop). Without this, "no request was sent" in the
/// tests below could be an artifact of the setup.
#[test]
fn open_pane_mid_batch_cancel_sends_the_follow_up() {
    App::test((), |mut app| async move {
        let batch = mid_batch(&mut app).await;
        batch.cancel_blocked_action(&mut app);
        let_subscribers_run().await;
        assert_eq!(*batch.sent_requests.borrow(), 1);
    })
}

/// #848 (blocker found in review): stopping a conversation mid-batch must not send a follow-up
/// from the closed pane. Closing cancels the batch's still-pending action; every cancellation
/// reaches the controller's `FinishedAction` subscriber, which sends the batch's results as a
/// follow-up when any of them -- here the earlier, successful one -- should trigger a request.
/// That request's auto-executable actions would then run in the closed pane's shell.
#[test]
fn closing_mid_batch_sends_no_follow_up_and_leaves_the_conversation_cancelled() {
    App::test((), |mut app| async move {
        let batch = mid_batch(&mut app).await;

        batch
            .terminal
            .update(&mut app, |view, ctx| view.suspend_agent_work_for_close(ctx));
        let_subscribers_run().await;

        assert_eq!(
            *batch.sent_requests.borrow(),
            0,
            "no follow-up from a closed pane"
        );
        assert_eq!(batch.status(&app), Some(ConversationStatus::Cancelled));
        let conversation_id = batch.conversation_id;
        batch.terminal.read(&app, |view, ctx| {
            assert!(
                !view
                    .ai_controller()
                    .as_ref(ctx)
                    .has_active_stream_for_conversation(conversation_id, ctx)
            );
            assert!(
                view.ai_action_model
                    .as_ref(ctx)
                    .get_finished_action_results(conversation_id)
                    .is_none_or(|results| results.is_empty()),
                "the batch's earlier results must not ride along with the next prompt"
            );
        });
    })
}

/// The controller guard on its own, without the close path's up-front discard of the batch's
/// earlier results: a suspended controller's `FinishedAction` subscriber sends nothing, puts
/// the conversation back to `Cancelled` (the action model had moved it to `InProgress` when
/// the mixed batch drained) and still unlocks a follow-up queued behind the approval.
#[test]
fn suspended_controller_mid_batch_cancel_sends_nothing_and_unlocks_the_queue() {
    App::test((), |mut app| async move {
        let batch = mid_batch(&mut app).await;
        let conversation_id = batch.conversation_id;
        QueuedQueryModel::handle(&app).update(&mut app, |model, ctx| {
            model.append(
                conversation_id,
                QueuedQuery::new(
                    "after the approval".to_owned(),
                    QueuedQueryOrigin::PendingApprovalFollowUp,
                ),
                ctx,
            );
        });

        batch.terminal.update(&mut app, |view, ctx| {
            view.ai_controller().update(ctx, |controller, _| {
                controller.set_suspended_for_close(true);
            });
        });
        batch.cancel_blocked_action(&mut app);
        let_subscribers_run().await;

        assert_eq!(*batch.sent_requests.borrow(), 0);
        assert_eq!(batch.status(&app), Some(ConversationStatus::Cancelled));
        QueuedQueryModel::handle(&app).read(&app, |model, _| {
            let queue = model.queue(conversation_id);
            assert_eq!(queue.len(), 1, "unlocked, not sent");
            assert_eq!(queue[0].origin(), QueuedQueryOrigin::ApprovalFollowUp);
        });
    })
}

impl MidBatch {
    /// Adds a tool that is really running (a grep whose execution never finishes) in front of
    /// the command that waits for approval: the state in which Ctrl-C and Stop differ (#2034).
    /// Returns the tool's id and its execution handle.
    fn start_running_tool(
        &self,
        app: &mut App,
    ) -> (AIAgentActionId, warpui::r#async::SpawnedFutureHandle) {
        let conversation_id = self.conversation_id;
        let task_id = BlocklistAIHistoryModel::handle(app).read(app, |history, _| {
            history
                .conversation(&conversation_id)
                .expect("conversation should exist")
                .get_root_task_id()
                .clone()
        });
        let tool_id = AIAgentActionId::from("running-grep".to_owned());
        let execution = self.action_model.update(app, |action_model, ctx| {
            let execution = ctx.spawn(futures::future::pending::<()>(), |_, (), _| {});
            action_model.start_running_async_action_for_test(
                crate::ai::agent::AIAgentAction {
                    id: tool_id.clone(),
                    task_id,
                    action: crate::ai::agent::AIAgentActionType::Grep {
                        queries: vec!["needle".to_owned()],
                        path: ".".to_owned(),
                    },
                    requires_result: true,
                },
                conversation_id,
                Some(execution.clone()),
                ctx,
            );
            execution
        });
        self.action_model.read(app, |action_model, _| {
            assert!(
                action_model
                    .get_action_status(&tool_id)
                    .is_some_and(|status| status.is_running()),
                "precondition: the tool is a running async action"
            );
            assert!(
                action_model
                    .get_action_status(&self.blocked_action_id)
                    .is_some_and(|status| !status.is_blocked() && !status.is_running()),
                "precondition: the command is queued behind the running tool"
            );
        });
        (tool_id, execution)
    }
}

/// #2034: a Ctrl-C typed while a tool runs that is not a shell command (a read, a search, an MCP
/// call) interrupts that tool and the turn goes on, as it does for a running command (#850,
/// owner decision 2026-11-10). The tool's work is aborted and its result is `cancelled`; the
/// command queued behind it is NOT cancelled with it and now waits for the user; nothing is
/// sent yet. When the user then answers that card (a Reject here), the step's results go back
/// to the model: nobody stopped the turn.
///
/// Red on the old code: the Ctrl-C cancelled the tool as a user stop (`ManuallyCancelled`).
#[test]
fn ctrl_c_on_a_running_tool_interrupts_it_and_the_turn_goes_on() {
    App::test((), |mut app| async move {
        let batch = mid_batch(&mut app).await;
        let (tool_id, execution) = batch.start_running_tool(&mut app);
        let conversation_id = batch.conversation_id;

        let interrupted = batch.action_model.update(&mut app, |action_model, ctx| {
            action_model.interrupt_running_actions(conversation_id, ctx)
        });
        let_subscribers_run().await;

        assert!(interrupted, "a running grep is interrupted as an action");
        assert!(
            execution.abort_handle().is_aborted(),
            "the tool's work is stopped, not left to finish"
        );
        batch.action_model.read(&app, |action_model, _| {
            assert!(
                action_model
                    .get_action_status(&tool_id)
                    .is_some_and(|status| !status.is_running()),
                "the interrupted tool has its result"
            );
            assert!(
                action_model
                    .get_action_status(&batch.blocked_action_id)
                    .is_some_and(|status| status.is_blocked()),
                "the command behind it was not cancelled: its card waits for the user"
            );
        });
        assert_eq!(
            *batch.sent_requests.borrow(),
            0,
            "nothing is sent while a card of the step still waits"
        );
        assert_ne!(
            batch.status(&app),
            Some(ConversationStatus::Cancelled),
            "the key did not stop the turn"
        );

        // The user answers the remaining card; the step ends by the ordinary rule and the model
        // is told (an earlier result of the step had finished).
        batch.cancel_blocked_action(&mut app);
        let_subscribers_run().await;
        assert_eq!(
            *batch.sent_requests.borrow(),
            1,
            "the turn went on: one follow-up carries the step's results"
        );
    })
}

/// #2034, the other half: a STOP of a running tool stops the turn. The command queued behind
/// the tool goes with it (as it always has when the stop lands on a card that still waits,
/// #1799), nothing is sent however much of the step had finished (#1942), and the turn ends
/// `Cancelled`. `cancel_action_with_id(.., ManuallyCancelled)` on a running action is what the
/// card's Reject of a running MCP call reaches; the status bar's Stop button goes through
/// `cancel_conversation_progress`, which cancels the same set.
///
/// Red on the old code: only the tool was cancelled, and the command's card came up after the
/// user had stopped the agent.
#[test]
fn stopping_a_running_tool_stops_the_rest_of_the_turn() {
    App::test((), |mut app| async move {
        let batch = mid_batch(&mut app).await;
        let (tool_id, execution) = batch.start_running_tool(&mut app);
        let conversation_id = batch.conversation_id;

        batch.action_model.update(&mut app, |action_model, ctx| {
            action_model.cancel_action_with_id(
                conversation_id,
                &tool_id,
                CancellationReason::ManuallyCancelled,
                ctx,
            );
        });
        let_subscribers_run().await;

        assert!(execution.abort_handle().is_aborted());
        batch.action_model.read(&app, |action_model, _| {
            assert!(
                !action_model.has_unfinished_actions_for_conversation(conversation_id),
                "nothing of the turn is left pending or running"
            );
            assert!(
                action_model
                    .get_action_status(&batch.blocked_action_id)
                    .is_none_or(|status| !status.is_blocked()),
                "no card comes up after a stop"
            );
        });
        assert_eq!(*batch.sent_requests.borrow(), 0, "Stop means stop (#1942)");
        assert_eq!(batch.status(&app), Some(ConversationStatus::Cancelled));
    })
}

#[test]
fn cmd_k_does_not_clear_buffer_when_agent_is_driving_command() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);

        let terminal = add_window_with_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            bootstrap_with_long_running_block(view);

            let conversation_id =
                BlocklistAIHistoryModel::handle(ctx).update(ctx, |history, ctx| {
                    // The pin passes a 4th `is_cli_agent_transcript` bool here (tied to
                    // #423's TranscriptScope work), which this fork's `start_new_conversation`
                    // does not yet have. This test never inspects transcript scope, so the
                    // fork's existing 4-arg call (equivalent to `is_cli_agent_transcript:
                    // false`) is behaviorally identical for this assertion. See the #418
                    // report for the arity-drift finding in full.
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });
            set_active_block_agent_driving(view, conversation_id);

            assert!(
                view.model
                    .lock()
                    .block_list()
                    .active_block()
                    .is_agent_driving_command()
            );
            assert!(
                !view
                    .model
                    .lock()
                    .block_list()
                    .active_block()
                    .is_agent_monitoring()
            );

            let block_count_before = view.model.lock().block_list().blocks().len();

            view.clear_buffer_for_testing(ctx);

            assert_eq!(
                view.model.lock().block_list().blocks().len(),
                block_count_before,
                "cmd-k must not wipe blocks while the agent is driving a command"
            );
        });
    })
}

#[test]
fn cmd_k_in_agent_view_clears_active_block_not_full_buffer_when_agent_driving_command() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        FeatureFlag::AgentView.set_enabled(true);

        let terminal = add_window_with_terminal(&mut app, None);

        let conversation_id = terminal.update(&mut app, |view, ctx| {
            let conversation_id = view.agent_view_controller().update(ctx, |controller, ctx| {
                controller
                    .try_enter_agent_view(
                        None,
                        AgentViewEntryOrigin::Input {
                            was_prompt_autodetected: false,
                        },
                        ctx,
                    )
                    .expect("should enter agent view")
            });

            bootstrap_with_long_running_block(view);
            set_active_block_agent_driving(view, conversation_id);

            assert!(
                view.agent_view_controller()
                    .as_ref(ctx)
                    .agent_view_state()
                    .is_fullscreen()
            );
            assert!(
                view.model
                    .lock()
                    .block_list()
                    .active_block()
                    .is_agent_driving_command()
            );

            conversation_id
        });

        let block_count_before = terminal.read(&app, |view, _| {
            view.model.lock().block_list().blocks().len()
        });

        terminal.update(&mut app, |view, ctx| {
            view.clear_buffer_for_testing(ctx);
        });

        terminal.read(&app, |view, ctx| {
            // Same conversation still active: no new conversation was started.
            assert_eq!(
                view.agent_view_controller()
                    .as_ref(ctx)
                    .agent_view_state()
                    .active_conversation_id(),
                Some(conversation_id),
                "cmd-k must not start a new conversation while agent is driving a command"
            );
            // Block count unchanged: only the active block output was cleared.
            assert_eq!(
                view.model.lock().block_list().blocks().len(),
                block_count_before,
                "cmd-k must not remove blocks while agent is driving a command"
            );
        });
    })
}

// --- Conversation transfer between terminal surfaces (#418) ---

#[test]
fn appended_exchange_renders_in_current_terminal_surface_after_conversation_transfer() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);

        let original_view = add_window_with_terminal(&mut app, None);
        let transferred_view = add_window_with_terminal(&mut app, None);

        let original_view_id = original_view.read(&app, |view, _| view.view_id);
        let transferred_view_id = transferred_view.read(&app, |view, _| view.view_id);

        let conversation_id = original_view.update(&mut app, |view, ctx| {
            let (conversation_id, _, _, _) = append_exchange_with_inputs_and_handle_event(
                view,
                vec![AIAgentInput::UserQuery {
                    query: "first query".to_owned(),
                    context: Default::default(),
                    static_query_type: None,
                    referenced_attachments: Default::default(),
                    user_query_mode: UserQueryMode::Normal,
                    running_command: None,
                    intended_agent: None,
                }],
                ctx,
            );
            conversation_id
        });

        let restored_conversation =
            BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
                history
                    .conversation(&conversation_id)
                    .cloned()
                    .expect("conversation should exist")
            });

        transferred_view.update(&mut app, |view, ctx| {
            view.restore_conversation_after_view_creation(
                RestoredAIConversation::new(restored_conversation),
                true,
                RestoreConversationEntryBehavior::EnterRestoredConversation,
                ctx,
            );
        });

        BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
            assert_eq!(
                history.terminal_view_id_for_conversation(&conversation_id),
                Some(transferred_view_id)
            );
        });

        let original_view_block_count_after_restore =
            original_view.read(&app, |view, _| ai_block_count(view));
        let transferred_view_block_count_after_restore =
            transferred_view.read(&app, |view, _| ai_block_count(view));
        assert_eq!(transferred_view_block_count_after_restore, 1);

        let (task_id, exchange_id, response_stream_id) = BlocklistAIHistoryModel::handle(&app)
            .update(&mut app, |history, ctx| {
                let conversation = history
                    .conversation_mut(&conversation_id)
                    .expect("conversation should exist");
                let task_id = conversation.get_root_task_id().clone();
                let response_stream_id = ResponseStreamId::new_for_test();
                let exchange = exchange_with_inputs(vec![AIAgentInput::UserQuery {
                    query: "follow up".to_owned(),
                    context: Default::default(),
                    static_query_type: None,
                    referenced_attachments: Default::default(),
                    user_query_mode: UserQueryMode::Normal,
                    running_command: None,
                    intended_agent: None,
                }]);
                let exchange_id = exchange.id;
                conversation
                    .append_reassigned_exchange(
                        &response_stream_id,
                        exchange,
                        original_view_id,
                        ctx,
                    )
                    .expect("exchange should append");
                (task_id, exchange_id, response_stream_id)
            });

        original_view.update(&mut app, |view, ctx| {
            view.handle_ai_history_model_event(
                BlocklistAIHistoryModel::handle(ctx),
                &BlocklistAIHistoryEvent::AppendedExchange {
                    exchange_id,
                    task_id: task_id.clone(),
                    terminal_view_id: original_view_id,
                    conversation_id,
                    is_hidden: false,
                    response_stream_id: Some(response_stream_id.clone()),
                },
                ctx,
            );
        });

        transferred_view.update(&mut app, |view, ctx| {
            view.handle_ai_history_model_event(
                BlocklistAIHistoryModel::handle(ctx),
                &BlocklistAIHistoryEvent::AppendedExchange {
                    exchange_id,
                    task_id,
                    terminal_view_id: original_view_id,
                    conversation_id,
                    is_hidden: false,
                    response_stream_id: Some(response_stream_id),
                },
                ctx,
            );
        });

        original_view.read(&app, |view, _| {
            assert_eq!(
                ai_block_count(view),
                original_view_block_count_after_restore
            );
        });
        transferred_view.read(&app, |view, _| {
            assert_eq!(
                ai_block_count(view),
                transferred_view_block_count_after_restore + 1
            );
        });
    })
}

#[test]
fn restoring_conversation_to_new_pane_transfers_blocks_from_previous_terminal_surface() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);

        let original_view = add_window_with_terminal(&mut app, None);
        let restored_view = add_window_with_terminal(&mut app, None);

        let original_view_id = original_view.read(&app, |view, _| view.view_id);
        let restored_view_id = restored_view.read(&app, |view, _| view.view_id);

        let conversation_id = original_view.update(&mut app, |view, ctx| {
            let (conversation_id, _, _, _) = append_exchange_with_inputs_and_handle_event(
                view,
                vec![AIAgentInput::UserQuery {
                    query: "first query".to_owned(),
                    context: Default::default(),
                    static_query_type: None,
                    referenced_attachments: Default::default(),
                    user_query_mode: UserQueryMode::Normal,
                    running_command: None,
                    intended_agent: None,
                }],
                ctx,
            );
            view.insert_agent_view_entry_block(
                AgentViewEntryBlockParams {
                    conversation_id,
                    is_new: false,
                    is_restored: false,
                    origin: AgentViewEntryOrigin::AgentViewBlock,
                    agent_view_controller: view.agent_view_controller().clone(),
                },
                RichContentInsertionPosition::Append {
                    insert_below_long_running_block: false,
                },
                ctx,
            );
            {
                let mut model = view.model.lock();
                model.simulate_block("agent command", "agent output");
                let command_block_index = model.block_list().blocks().len() - 2;
                model.block_list_mut().blocks_mut()[command_block_index]
                    .set_conversation_id(conversation_id);
            }
            conversation_id
        });

        original_view.read(&app, |view, _| {
            assert_eq!(ai_block_count(view), 1);
            assert_eq!(
                agent_view_entry_count_for_conversation(view, conversation_id),
                1
            );
            assert_eq!(
                command_block_count_for_conversation(view, conversation_id),
                1
            );
        });

        let restored_conversation =
            BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
                history
                    .conversation(&conversation_id)
                    .cloned()
                    .expect("conversation should exist")
            });

        restored_view.update(&mut app, |view, ctx| {
            view.restore_conversation_after_view_creation(
                RestoredAIConversation::new(restored_conversation),
                true,
                RestoreConversationEntryBehavior::EnterRestoredConversation,
                ctx,
            );
        });

        BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
            let original_view_live_conversation_ids = history
                .all_live_conversations_for_terminal_view(original_view_id)
                .map(|conversation| conversation.id())
                .collect::<Vec<_>>();
            let restored_view_live_conversation_ids = history
                .all_live_conversations_for_terminal_view(restored_view_id)
                .map(|conversation| conversation.id())
                .collect::<Vec<_>>();
            assert_eq!(
                history.terminal_view_id_for_conversation(&conversation_id),
                Some(restored_view_id)
            );
            assert!(original_view_live_conversation_ids.is_empty());
            assert_eq!(restored_view_live_conversation_ids, vec![conversation_id]);
        });

        original_view.read(&app, |view, _| {
            assert_eq!(ai_block_count(view), 0);
            assert_eq!(
                agent_view_entry_count_for_conversation(view, conversation_id),
                1
            );
            assert_eq!(
                command_block_count_for_conversation(view, conversation_id),
                0
            );
        });
        restored_view.read(&app, |view, _| {
            assert_eq!(ai_block_count(view), 1);
        });
    })
}

