/// Ctrl-D at the prompt with nothing typed would exit the shell; it is not written.
#[test]
fn typeahead_handoff_ctrl_d_on_an_empty_shell_line_is_not_written() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = collect_pty_writes(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| {
            {
                let mut model = view.model.lock();
                model.block_list_mut().set_bootstrapped();
                let mut handoff = model.typeahead_handoff_mut();
                handoff.on_command_written();
                // A further Enter the shell answers with a prompt; both prompts have come.
                handoff.on_user_bytes(b"\r");
                handoff.on_precmd();
                handoff.on_precmd();
                assert!(handoff.routes_keys_to_pty());
            }
            view.ctrl_d(ctx);
            // With bytes in the shell's line, Ctrl-D is an edit there and is written.
            view.model
                .lock()
                .typeahead_handoff_mut()
                .on_user_bytes(b"ab");
            view.ctrl_d(ctx);
        });

        assert_eq!(*pty_writes.borrow(), vec![vec![escape_sequences::C0::EOT]]);
    })
}

/// Keys typed into a full-screen program (vim's `:wq` Enter) are written but are not lines for
/// the shell: they must not leave the hand-off waiting for a prompt that never comes.
#[test]
fn typeahead_handoff_does_not_count_full_screen_enters() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = collect_pty_writes(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| {
            {
                let mut model = view.model.lock();
                model.simulate_long_running_block("vim", "");
                model.set_mode(ansi::Mode::SwapScreen {
                    save_cursor_and_clear_screen: true,
                });
                assert!(model.is_alt_screen_active());
                model.typeahead_handoff_mut().on_command_written();
            }
            view.keydown_on_terminal("\r", ctx);
        });

        assert_eq!(*pty_writes.borrow(), vec![b"\r".to_vec()]);
        terminal.read(&app, |view, _| {
            assert_eq!(
                view.model.lock().typeahead_handoff().state(),
                &HandoffState::PtyOwned {
                    wrote_user_bytes: false,
                    enters_written: 1,
                    precmds_seen: 0,
                }
            );
        });
    })
}

/// After a Ctrl-C the settle timer asks the controller to decide again while the pty still owns
/// input, for a killed command as much as at the prompt: if the counts were off (an Enter a
/// program consumed), no precmd would otherwise hand input back.
#[test]
fn typeahead_handoff_ctrl_c_settle_asks_for_a_new_decision() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        let retries = Rc::new(RefCell::new(0));
        let retries_seen = retries.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if let Event::RetryTypeaheadHandoffRequest = event {
                    *retries_seen.borrow_mut() += 1;
                }
            });
        });

        terminal.update(&mut app, |view, ctx| {
            {
                let mut model = view.model.lock();
                model.start_command_execution();
                model.typeahead_handoff_mut().on_command_written();
            }
            view.ctrl_c(ctx);
            let model = view.model.lock();
            assert!(model.typeahead_handoff().is_pty_owned());
        });
        assert_eq!(*retries.borrow(), 0);

        let deadline = Instant::now() + Duration::from_secs(3);
        while *retries.borrow() == 0 && Instant::now() < deadline {
            Timer::after(Duration::from_millis(50)).await;
        }
        assert_eq!(*retries.borrow(), 1);
    })
}

/// Drives the hand-off to "Enter deferred while the report is outstanding".
fn hold_after_deferred_enter(view: &TerminalView) {
    let mut model = view.model.lock();
    let mut handoff = model.typeahead_handoff_mut();
    handoff.on_command_written();
    handoff.on_user_bytes(b"ec");
    handoff.on_user_write_flushed();
    handoff.on_precmd();
    assert_eq!(
        handoff.on_line_editor_active(true, true),
        ActiveDecision::SendRequest
    );
    assert!(handoff.defer_enter());
}

/// #850 x the typeahead hand-off: ctrl-c on an agent command in flight while keys are held
/// behind a deferred Enter still discards the parked copy and sends exactly one ^C -- it is not
/// swallowed by the hold. The deferred Enter is dropped.
#[test]
fn typeahead_handoff_ctrl_c_on_an_agent_command_is_not_held() {
    App::test((), |mut app| async move {
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let (terminal, _conversation_id, _action_id) =
            terminal_with_real_async_agent_command(&mut app, false);
        terminal.update(&mut app, |view, _| {
            view.model
                .lock()
                .block_list_mut()
                .active_block_mut()
                .start();
            hold_after_deferred_enter(view);
        });
        let sequence: Rc<RefCell<Vec<&'static str>>> = Rc::new(RefCell::new(Vec::new()));
        let recorded = sequence.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| match event {
                Event::DiscardPendingCommandWrites => recorded.borrow_mut().push("discard"),
                Event::WriteBytesToPty { bytes } | Event::WriteHandoffUserBytesToPty { bytes }
                    if bytes.contains(&C0::ETX) =>
                {
                    recorded.borrow_mut().push("etx")
                }
                _ => {}
            });
        });

        terminal.update(&mut app, |view, ctx| {
            view.handle_action(&TerminalAction::CtrlC, ctx);
        });

        assert_eq!(*sequence.borrow(), vec!["discard", "etx"]);
        terminal.read(&app, |view, _| {
            assert_eq!(
                view.model.lock().typeahead_handoff().state(),
                &HandoffState::AwaitingReport
            );
        });
    })
}

/// #1774: the interrupt paths that write their own ^C, other than the key and the agent-command
/// interrupt.
#[derive(Clone, Copy, Debug)]
enum InterruptCtrlCPath {
    /// Stop of a conversation whose running command is the user's own (not agent-requested).
    StopUserCommand,
    SshWarpifyInterrupt,
    Rewind,
}

/// #1774: every interrupt path that writes a ^C cancels an Enter deferred behind the typeahead
/// report (and the keys held behind it) first, as `ctrl_c` and `interrupt_agent_command` do: the
/// ^C reaches the pty once, at once, instead of being held behind the deferred Enter's gate and
/// replayed after the command it was meant to interrupt. The key typed behind the Enter is voided
/// with it (a tty flushes typeahead on an interrupt), never written.
#[test]
fn an_interrupt_ctrl_c_is_not_held_behind_a_deferred_enter() {
    for path in [
        InterruptCtrlCPath::StopUserCommand,
        InterruptCtrlCPath::SshWarpifyInterrupt,
        InterruptCtrlCPath::Rewind,
    ] {
        App::test((), move |mut app| async move {
            let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
            initialize_app_for_terminal_view(&mut app);
            register_global_resource_handles(&mut app);
            let terminal = add_window_with_terminal(&mut app, None);
            let conversation_id = terminal.update(&mut app, |view, ctx| {
                let conversation_id = start_running_conversation_for_close(view, ctx);
                let mut model = view.model.lock();
                model.simulate_long_running_block("sleep 100", "");
                if matches!(path, InterruptCtrlCPath::Rewind) {
                    // A rewind stops a running command of its own conversation.
                    model
                        .block_list_mut()
                        .active_block_mut()
                        .set_agent_interaction_mode_for_requested_command(
                            AIAgentActionId::from("requested-command".to_owned()),
                            None,
                            conversation_id,
                        );
                }
                conversation_id
            });
            let pty_writes = collect_pty_writes(&mut app, &terminal);
            terminal.update(&mut app, |view, ctx| {
                hold_after_deferred_enter(view);
                view.write_user_bytes_to_pty(b"x".to_vec(), ctx);
                assert_eq!(
                    view.model.lock().typeahead_handoff().state(),
                    &HandoffState::HoldAfterEnter { released: false },
                    "{path:?}"
                );
            });
            assert!(pty_writes.borrow().is_empty(), "{path:?}");
            terminal.update(&mut app, |view, ctx| match path {
                InterruptCtrlCPath::StopUserCommand => {
                    view.stop_local_agent_conversation(conversation_id, ctx)
                }
                InterruptCtrlCPath::SshWarpifyInterrupt => {
                    view.handle_ssh_warpify_block_event(&SshWarpifyBlockEvent::Interrupt, ctx)
                }
                InterruptCtrlCPath::Rewind => view.rewind_ai_conversation(
                    EntityId::new(),
                    AIAgentExchangeId::new(),
                    conversation_id,
                    ctx,
                ),
            });
            let writes = pty_writes.borrow().clone();
            assert_eq!(
                writes
                    .iter()
                    .filter(|bytes| bytes.contains(&C0::ETX))
                    .count(),
                1,
                "{path:?}: one ^C reached the pty: {writes:?}"
            );
            assert!(
                !writes.iter().any(|bytes| bytes.contains(&b'x')),
                "{path:?}: the key behind the Enter was voided: {writes:?}"
            );
            terminal.read(&app, |view, _| {
                assert_ne!(
                    view.model.lock().typeahead_handoff().state(),
                    &HandoffState::HoldAfterEnter { released: false },
                    "{path:?}: the deferred Enter was cancelled"
                );
            });
        });
    }
}

/// #1331: a terminal-bound paste whose clipboard read never answers fails at the backstop; the
/// keys typed meanwhile are WRITTEN TO THE PTY in typed order, once (none dropped, none handed to
/// the editor), and the reader's late answer writes nothing.
///
/// Expectation history (re-decided by the owner, never weakened): the pty write (original); a
/// hand-back to the editor (`ls\n` in the buffer, nothing at the pty: owner rule 2026-11-01,
/// #1577, when this test was named
/// `stalled_pty_paste_hands_held_keys_back_in_order_at_the_backstop`);
/// and the pty write again: owner decision 2 of 2026-11-09 (#1996 follow-up: the paste has no
/// content and is discarded with its own notice, the keys typed behind it go to the pty).
#[test]
fn stalled_pty_paste_writes_held_keys_to_the_pty_in_order_at_the_backstop() {
    use warpui::clipboard::{BackgroundTextRead, BackgroundTextReader};
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes: Rc<RefCell<Vec<Vec<u8>>>> = Rc::new(RefCell::new(Vec::new()));
        let writes = pty_writes.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if let Event::WriteBytesToPty { bytes } = event {
                    writes.borrow_mut().push(bytes.to_vec());
                }
            });
        });
        let (release, parked) = std::sync::mpsc::channel::<()>();
        let reader: BackgroundTextReader = Box::new(move || {
            let _ = parked.recv_timeout(Duration::from_secs(20));
            BackgroundTextRead::Content(ClipboardContent::plain_text("LATE".to_string()))
        });
        terminal.update(&mut app, |view, ctx| {
            view.start_background_paste_with_backstop(
                reader,
                None,
                false,
                Some(Duration::from_millis(100)),
                ctx,
            );
            for key in [b"l".to_vec(), b"s".to_vec(), b"\r".to_vec()] {
                assert!(view.write_user_bytes_to_pty(key, ctx));
            }
        });
        assert!(
            pty_writes.borrow().is_empty(),
            "keys typed behind a pending paste are held"
        );
        for _ in 0..1000 {
            if !terminal.read(&app, |view, _| view.paste_pending()) {
                break;
            }
            warpui::r#async::Timer::after(Duration::from_millis(5)).await;
        }
        let buffer_of =
            |app: &App| terminal.read(app, |view, ctx| view.input.as_ref(ctx).buffer_text(ctx));
        assert_eq!(
            pty_writes.borrow().concat(),
            b"ls\r".to_vec(),
            "the backstop writes the held keys to the pty, once, in typed order"
        );
        assert_eq!(buffer_of(&app), "", "nothing is handed to the editor");
        release.send(()).unwrap();
        warpui::r#async::Timer::after(Duration::from_millis(100)).await;
        assert_eq!(
            pty_writes.borrow().concat(),
            b"ls\r".to_vec(),
            "the late answer is ignored: the paste is never written"
        );
        assert_eq!(
            buffer_of(&app),
            "",
            "the late answer puts nothing into the editor"
        );
    })
}

/// What a pty-bound paste scenario does.
#[derive(Clone, Copy, Debug)]
enum PtyPasteScenario {
    /// The read answers after the keys were typed.
    SlowRead,
    /// The clipboard owner never answers (the reader reports a time-out).
    FailedRead,
    /// The clipboard is over the paste size cap (the reader reports `TooLarge`, #1382).
    TooLargeRead,
    /// Ctrl-C is typed while the read is pending.
    CtrlC,
    /// The reader parks past the 100 ms backstop, then answers late.
    BackstopThenLateResult,
}

/// Runs one pty-paste scenario on the queue path and returns every byte that reached the pty, in
/// order (#1353 phase 1).
async fn pty_paste_bytes(app: &mut App, scenario: PtyPasteScenario) -> Vec<u8> {
    use warpui::clipboard::{BackgroundTextRead, BackgroundTextReader};
    initialize_app_for_terminal_view(app);
    let terminal = add_window_with_terminal(app, None);
    let pty_writes: Rc<RefCell<Vec<Vec<u8>>>> = Rc::new(RefCell::new(Vec::new()));
    let writes = pty_writes.clone();
    app.update(|ctx| {
        ctx.subscribe_to_view(&terminal, move |_, event, _| match event {
            Event::WriteBytesToPty { bytes } | Event::WriteHandoffUserBytesToPty { bytes } => {
                writes.borrow_mut().push(bytes.to_vec())
            }
            _ => {}
        });
    });
    let (release, parked) = std::sync::mpsc::channel::<()>();
    let fails = matches!(scenario, PtyPasteScenario::FailedRead);
    let too_large = matches!(scenario, PtyPasteScenario::TooLargeRead);
    let reader: BackgroundTextReader = Box::new(move || {
        let _ = parked.recv_timeout(Duration::from_secs(20));
        if fails {
            BackgroundTextRead::TimedOut
        } else if too_large {
            BackgroundTextRead::TooLarge(warpui::clipboard::MAX_PASTE_BYTES + 1)
        } else {
            BackgroundTextRead::Content(ClipboardContent::plain_text("PASTE".to_string()))
        }
    });
    let backstop = match scenario {
        PtyPasteScenario::BackstopThenLateResult => Some(Duration::from_millis(100)),
        _ => None,
    };
    terminal.update(app, |view, ctx| {
        // Typed before the paste: goes straight out.
        assert!(view.write_user_bytes_to_pty(b"a".to_vec(), ctx));
        view.start_background_paste_with_backstop(reader, None, false, backstop, ctx);
        assert!(view.paste_pending(), "the read is pending");
        assert!(
            !view.paste_queue.queue.borrow().is_idle(),
            "the queue holds the paste"
        );
        let typed: &[&[u8]] = match scenario {
            PtyPasteScenario::CtrlC => &[b"l", b"\x03"],
            _ => &[b"l", b"s", b"\r"],
        };
        for key in typed {
            assert!(view.write_user_bytes_to_pty(key.to_vec(), ctx));
        }
    });
    let flat = |writes: &Rc<RefCell<Vec<Vec<u8>>>>| -> Vec<u8> {
        writes.borrow().iter().flatten().copied().collect()
    };
    match scenario {
        PtyPasteScenario::CtrlC => {
            // The paste is cancelled on the spot: what was typed before the abort, then the abort.
            assert!(!terminal.read(app, |view, _| view.paste_pending()));
            assert_eq!(flat(&pty_writes), b"al\x03".to_vec());
            release.send(()).unwrap();
            warpui::r#async::Timer::after(Duration::from_millis(100)).await;
            assert_eq!(
                flat(&pty_writes),
                b"al\x03".to_vec(),
                "the cancelled paste is never written, even when the read answers"
            );
        }
        PtyPasteScenario::BackstopThenLateResult => {
            for _ in 0..1000 {
                if !terminal.read(app, |view, _| view.paste_pending()) {
                    break;
                }
                warpui::r#async::Timer::after(Duration::from_millis(5)).await;
            }
            // Owner decision 2 of 2026-11-09 (#1996 follow-up, reversing #1577's hand-back, under
            // which this scenario expected only `a` at the pty and `ls\n` in the editor): the
            // paste has no content and is discarded; the keys typed behind it are written to the
            // pty at the backstop, in typed order, after the key typed before the paste.
            assert_eq!(
                flat(&pty_writes),
                b"als\r".to_vec(),
                "the keys behind the unread paste are written at the backstop, in typed order"
            );
            assert_eq!(
                terminal.read(app, |view, ctx| view.input.as_ref(ctx).buffer_text(ctx)),
                "",
                "nothing is handed to the editor at the backstop"
            );
            release.send(()).unwrap();
            warpui::r#async::Timer::after(Duration::from_millis(100)).await;
            assert_eq!(
                flat(&pty_writes),
                b"als\r".to_vec(),
                "the late result is ignored: the paste is never written"
            );
        }
        PtyPasteScenario::SlowRead
        | PtyPasteScenario::FailedRead
        | PtyPasteScenario::TooLargeRead => {
            assert_eq!(
                flat(&pty_writes),
                b"a".to_vec(),
                "keys typed behind the pending paste are held"
            );
            release.send(()).unwrap();
            for _ in 0..1000 {
                if !terminal.read(app, |view, _| view.paste_pending()) {
                    break;
                }
                warpui::r#async::Timer::after(Duration::from_millis(5)).await;
            }
        }
    }
    flat(&pty_writes)
}

/// #1353 phase 1: a slow clipboard read with keys (and an Enter) typed behind it. The keys wait for
/// the read, the paste goes out first, then `ls\r`: typed order. Same bytes on the legacy path.
#[test]
fn pty_paste_with_keys_and_enter_behind_a_slow_read_delivers_in_typed_order() {
    App::test((), move |mut app| async move {
        let written = pty_paste_bytes(&mut app, PtyPasteScenario::SlowRead).await;
        assert_eq!(written, b"aPASTEls\r".to_vec());
    });
}

/// #1389, pty / alt-screen destination: cursor keys (Left, End as escape sequences) and the text
/// typed behind a LARGE paste that is still being read go to the pty after the whole paste, in
/// typed order; nothing is written before the paste, lost or duplicated. Both destination modes.
#[test]
fn pty_cursor_keys_behind_a_large_pending_paste_follow_it_in_order() {
    use warpui::clipboard::{BackgroundTextRead, BackgroundTextReader};
    for size in [100 * 1024usize, 1024 * 1024] {
        App::test((), move |mut app| async move {
            initialize_app_for_terminal_view(&mut app);
            let terminal = add_window_with_terminal(&mut app, None);
            let pty_writes: Rc<RefCell<Vec<Vec<u8>>>> = Rc::new(RefCell::new(Vec::new()));
            let writes = pty_writes.clone();
            app.update(|ctx| {
                ctx.subscribe_to_view(&terminal, move |_, event, _| match event {
                    Event::WriteBytesToPty { bytes }
                    | Event::WriteHandoffUserBytesToPty { bytes } => {
                        writes.borrow_mut().push(bytes.to_vec())
                    }
                    _ => {}
                });
            });
            let pasted = "p".repeat(size);
            let content = pasted.clone();
            let (release, parked) = std::sync::mpsc::channel::<()>();
            let reader: BackgroundTextReader = Box::new(move || {
                let _ = parked.recv_timeout(Duration::from_secs(20));
                BackgroundTextRead::Content(ClipboardContent::plain_text(content))
            });
            terminal.update(&mut app, |view, ctx| {
                assert!(view.write_user_bytes_to_pty(b"a".to_vec(), ctx));
                view.start_background_paste_with_backstop(reader, None, false, None, ctx);
                assert!(view.paste_pending(), "the read is pending");
                for key in [&b"x"[..], b"y", b"\x1b[D", b"z", b"\x1b[F", b"!"] {
                    assert!(view.write_user_bytes_to_pty(key.to_vec(), ctx));
                }
            });
            let flat = |writes: &Rc<RefCell<Vec<Vec<u8>>>>| -> Vec<u8> {
                writes.borrow().iter().flatten().copied().collect()
            };
            assert_eq!(
                flat(&pty_writes),
                b"a".to_vec(),
                "keys typed behind the pending paste are held"
            );
            release.send(()).unwrap();
            for _ in 0..4000 {
                if !terminal.read(&app, |view, _| view.paste_pending()) {
                    break;
                }
                warpui::r#async::Timer::after(Duration::from_millis(5)).await;
            }
            let mut expected = b"a".to_vec();
            expected.extend_from_slice(pasted.as_bytes());
            expected.extend_from_slice(b"xy\x1b[Dz\x1b[F!");
            let written = flat(&pty_writes);
            assert_eq!(written.len(), expected.len(), "size {size}");
            assert!(
                written == expected,
                "size {size}: the pty saw the keys out of order"
            );
        });
    }
}

