/// #1016: keys that reach the editor after an Enter that waits for the shell's report (the
/// focused editor can take them before the terminal does) are not part of the line that Enter
/// submits. The submit sees only the text typed before the Enter, and the later keys follow it,
/// ahead of the keys already held, in typed order.
///
/// Expectation history (owner decision 2026-11-09 on #1997, "keep them together" on the event
/// path; a changed decision, not a weakened test): since #826 N1 / #1016 this test expected
/// `echo 2` + Enter at the pty the moment the report arrived, while the line typed BEFORE it
/// (`true`) had not run: the test shell is not ready for a command, so `true` was held for it
/// (#1571) and the later line ran first. Now nothing is written while `true` waits; `echo 2` and
/// its Enter wait behind it in the queue, and the hold's give-up writes `true`, its Enter,
/// `echo 2`, its Enter, in that order. The #1016 claim itself is still asserted: `echo 2` never
/// joins the submitted line.
#[test]
fn typeahead_handoff_keys_the_editor_took_after_a_deferred_enter_do_not_join_its_line() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = collect_pty_writes(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| {
            awaiting_typeahead_report(view);
            view.input
                .update(ctx, |input, ctx| input.replace_buffer_content("true", ctx));
            view.input.update(ctx, |input, ctx| input.input_enter(ctx));
            assert!(
                !view
                    .model
                    .lock()
                    .typeahead_handoff()
                    .deferred_submit_pending()
            );
            // The event that follows the deferral opens the Enter's gate (in the app it is
            // delivered between two user events).
            view.open_deferred_enter_gate(ctx);
            // The next keys of the same burst reach the editor before the terminal routes them:
            // they are entries behind the gate, never text in the buffer.
            view.input.update(ctx, |input, ctx| {
                input.editor().update(ctx, |editor, ctx| {
                    editor.apply_held_paste_key(crate::editor::HeldPasteKey::Text("ec".into()), ctx)
                })
            });
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "true");
            // The rest of the burst, and its Enter, are routed to the same gate.
            view.write_user_bytes_to_pty(b"ho 2\r".to_vec(), ctx);
            view.handle_typeahead_report_with_handoff(true, ctx);

            assert_eq!(
                view.input.as_ref(ctx).buffer_text(ctx),
                "true",
                "what was typed after the Enter must not be part of the submitted line"
            );
            // #1997: `true` is held for the unready shell, so the line typed after it waits
            // behind it: nothing reaches the pty ahead of `true`.
            assert!(view.input.as_ref(ctx).unready_enter_gate_open());
            assert_eq!(
                view.paste_queue.queue.borrow().queued_len(),
                2,
                "`ec` and `ho 2` + Enter still wait, in place"
            );
        });
        // Checked after the update, when the write events it emitted have been delivered.
        assert!(
            pty_writes.borrow().is_empty(),
            "the later line must not run before `true`: {:?}",
            pty_writes.borrow()
        );
        // The hold's net: the line, its Enter, then what was typed after it.
        terminal.update(&mut app, |view, ctx| {
            view.input
                .update(ctx, |input, ctx| input.give_up_unready_enter("test", ctx));
        });

        assert_eq!(
            String::from_utf8_lossy(&pty_writes.borrow().concat()),
            "true\recho 2\r",
            "typed order: the held line and its Enter first, then the line typed after it"
        );
        terminal.read(&app, |view, ctx| {
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "");
            assert!(view.paste_queue.queue.borrow().is_idle());
        });
    })
}

/// #1997 (owner decision 2026-11-09, "keep them together" on the event path), at the NET:
/// `cd build`, Enter, `make clean`, Enter typed while the shell's report is outstanding. The
/// report arrives, the deferred Enter is submitted and the shell cannot take a command yet, so
/// `cd build` is held for it (#1571). `make clean` must not be written to the pty ahead of it
/// (it ran first, in the wrong directory): nothing is written while `cd build` waits, the keys
/// stay queued behind its gate, and the 60 s net writes `cd build`, Enter, `make clean`, Enter
/// in that order.
#[test]
fn a_line_typed_behind_a_deferred_enter_never_reaches_the_pty_before_that_enters_held_line() {
    use crate::terminal::input_queue::GateKind;
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = collect_pty_writes(&mut app, &terminal);
        let executed = count_executed_commands(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| {
            awaiting_typeahead_report(view);
            view.input.update(ctx, |input, ctx| {
                input.replace_buffer_content("cd build", ctx)
            });
            view.input.update(ctx, |input, ctx| input.input_enter(ctx));
            view.open_deferred_enter_gate(ctx);
            // The next line and its Enter, typed on the terminal behind the deferred Enter.
            view.write_user_bytes_to_pty(b"make clean\r".to_vec(), ctx);
            // In-update recorder read, always empty here: the read after this update (still
            // empty) carries it.
            assert!(pty_writes.borrow().is_empty());
            view.handle_typeahead_report_with_handoff(true, ctx);

            let input = view.input.as_ref(ctx);
            assert!(
                input.unready_enter_gate_open(),
                "`cd build` is held for the unready shell"
            );
            assert_eq!(input.buffer_text(ctx), "cd build");
            let queue = view.paste_queue.queue.borrow();
            assert!(
                !queue.has_gate_kind(GateKind::HandoffReport),
                "the deferred Enter's gate is closed"
            );
            assert_eq!(
                queue.queued_len(),
                1,
                "`make clean` + Enter waits behind the held line, in place"
            );
            assert_eq!(
                input.enter_gate_held_len_for_test(ctx),
                1,
                "behind the held Enter's own gate"
            );
        });
        // Checked after the update, when the write events it emitted have been delivered.
        assert!(
            pty_writes.borrow().is_empty(),
            "`make clean` must not reach the pty before `cd build`: {:?}",
            pty_writes.borrow()
        );
        assert_eq!(*executed.borrow(), 0, "nothing ran");

        terminal.update(&mut app, |view, ctx| {
            view.input
                .update(ctx, |input, ctx| input.give_up_unready_enter("test", ctx));
        });
        assert_eq!(
            String::from_utf8_lossy(&pty_writes.borrow().concat()),
            "cd build\rmake clean\r",
            "line one, Enter, line two, Enter, in typed order, once"
        );
        terminal.read(&app, |view, ctx| {
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "");
            assert!(view.paste_queue.queue.borrow().is_idle());
        });
    });
}

/// #1997, at READINESS: the same typing, and the shell becomes ready. Nothing reaches the pty
/// and nothing runs until then; the readiness event runs `cd build`, alone; only after it has
/// run is `make clean` + Enter released, once, to wherever keys typed at that moment belong (the
/// running command's tty, or the next prompt). The release is the gate's own (#1571); this test
/// is about the order.
///
/// Round 10 (#2010): the Legacy arm failed with `pty=[]` although the queue was empty and no gate
/// was open. The test listened for `WriteBytesToPty` only; see the recorder below. The Table arm
/// has never run (Legacy is first in the loop and panicked).
#[test]
fn a_line_typed_behind_a_deferred_enter_follows_that_enters_held_line_at_readiness() {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        // Both kinds of pty write. `make clean` is released into the running `cd build`,
        // a command the hand-off did not write: the hand-off adopts those keys (#1089) and
        // they go out through its counted route (`WriteHandoffUserBytesToPty`), which
        // `record_pty_writes` does not see. In the app the line's own write makes the
        // hand-off pty-owned, so the release is a counted write there too.
        let pty_writes = record_all_pty_writes(&mut app, &terminal);
        let executed: Rc<RefCell<Vec<String>>> = Rc::new(RefCell::new(Vec::new()));
        let sink = executed.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if let Event::ExecuteCommand(e) = event {
                    sink.borrow_mut().push(e.command.clone());
                }
            });
        });
        // Everything typed that is not `cd build`: where `make clean` is, and how often.
        let typed_after = |pty: &[Vec<u8>], executed: &[String], buffer: &str| {
            let pty: Vec<u8> = pty.iter().flatten().copied().collect();
            String::from_utf8_lossy(&pty).matches("make clean").count()
                + executed
                    .iter()
                    .filter(|command| command.contains("make clean"))
                    .count()
                + buffer.matches("make clean").count()
        };

        terminal.update(&mut app, |view, ctx| {
            // The prompt is up but the session is not registered with the history yet: the
            // shell refuses a command (#1572's window).
            register_local_session_for_ssh_test(view, ctx);
            view.model
                .lock()
                .block_list_mut()
                .active_block_for_test()
                .set_session_id(SessionId::from(9001));
            awaiting_typeahead_report(view);
            view.input.update(ctx, |input, ctx| {
                input.replace_buffer_content("cd build", ctx)
            });
            view.input.update(ctx, |input, ctx| input.input_enter(ctx));
            view.open_deferred_enter_gate(ctx);
            view.write_user_bytes_to_pty(b"make clean\r".to_vec(), ctx);
            view.handle_typeahead_report_with_handoff(true, ctx);

            let input = view.input.as_ref(ctx);
            assert!(
                input.has_held_unready_enter() && input.unready_enter_gate_open(),
                "`cd build` is held for the unready shell"
            );
            assert_eq!(
                view.paste_queue.queue.borrow().queued_len(),
                1,
                "`make clean` + Enter waits behind it"
            );
        });
        assert!(executed.borrow().is_empty(), "nothing ran");
        assert!(
            pty_writes.borrow().is_empty(),
            "nothing typed reached the pty before the shell was ready: {:?}",
            pty_writes.borrow()
        );

        // The readiness event: the held line runs, alone.
        terminal.update(&mut app, |view, ctx| {
            first_precmd_processed_for_test(view, ctx);
            view.retry_held_unready_enter("session_bootstrapped", ctx);
        });
        assert_eq!(
            *executed.borrow(),
            ["cd build".to_owned()],
            "the held line ran once, first"
        );
        assert_eq!(
            typed_after(&pty_writes.borrow(), &[], ""),
            0,
            "`make clean` did not reach the pty with or before `cd build`: {:?}",
            pty_writes.borrow()
        );
        // The pty takes the command: the keys behind it are released.
        terminal.update(&mut app, |view, ctx| {
            view.model
                .lock()
                .simulate_long_running_block("cd build", "");
            view.settle_enter_queue(ctx);
        });
        for _ in 0..200 {
            let released = terminal.read(&app, |view, ctx| {
                !view.input.as_ref(ctx).enter_queue_holds_keys(ctx)
                    && view.paste_queue.queue.borrow().is_idle()
            });
            if released {
                break;
            }
            warpui::r#async::Timer::after(std::time::Duration::from_millis(5)).await;
        }
        terminal.read(&app, |view, ctx| {
            assert!(
                view.paste_queue.queue.borrow().is_idle(),
                "the keys behind the held line were released"
            );
            let buffer = view.input.as_ref(ctx).buffer_text(ctx);
            assert_eq!(
                typed_after(&pty_writes.borrow(), &executed.borrow(), &buffer),
                1,
                "`make clean` was delivered exactly once, after `cd build`; \
                     pty={:?} executed={:?} buffer={buffer:?}",
                pty_writes.borrow(),
                executed.borrow()
            );
            assert_eq!(
                executed.borrow().first().map(String::as_str),
                Some("cd build"),
                "`cd build` ran first"
            );
        });
    });
}

/// #1016: a second Enter that reaches the editor while the first is deferred follows the keys
/// typed before it, in the hold; it never submits the editor.
#[test]
fn typeahead_handoff_a_second_editor_enter_is_held_behind_the_deferred_one() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = collect_pty_writes(&mut app, &terminal);
        let executed = count_executed_commands(&mut app, &terminal);

        terminal.update(&mut app, |view, ctx| {
            awaiting_typeahead_report(view);
            view.input
                .update(ctx, |input, ctx| input.replace_buffer_content("true", ctx));
            view.input.update(ctx, |input, ctx| input.input_enter(ctx));
            view.open_deferred_enter_gate(ctx);
            view.input.update(ctx, |input, ctx| {
                input.editor().update(ctx, |editor, ctx| {
                    editor.apply_held_paste_key(
                        crate::editor::HeldPasteKey::Text("echo 2".into()),
                        ctx,
                    )
                })
            });
            view.input.update(ctx, |input, ctx| input.input_enter(ctx));

            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "true");
            assert_eq!(
                view.model.lock().typeahead_handoff().state(),
                &HandoffState::HoldAfterEnter { released: false }
            );
            // `echo 2` and the Enter behind it wait as two entries behind the first Enter's gate.
            assert_eq!(view.paste_queue.queue.borrow().queued_len(), 2);
        });
        assert_eq!(*executed.borrow(), 0);
        assert!(pty_writes.borrow().is_empty());
    })
}

/// B2: the deferred submit is a shell command in Universal input too (the production default),
/// where the classic-mode setter does nothing; the lock covers that one submit and the previous
/// configuration comes back.
#[test]
fn typeahead_handoff_deferred_submit_is_a_shell_command_in_universal_input() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);
        InputSettings::handle(&app).update(&mut app, |input_settings, ctx| {
            let _ = input_settings
                .input_box_type
                .set_value(crate::settings::InputBoxType::Universal, ctx);
        });
        let ai_input_model = terminal.read(&app, |view, _| view.ai_input_model.clone());
        // Natural-language detection took the buffer for a query.
        ai_input_model.update(&mut app, |input_model, ctx| {
            input_model.set_input_type(InputType::AI, ctx)
        });
        let configs: Rc<RefCell<Vec<InputType>>> = Rc::new(RefCell::new(Vec::new()));
        let recorded = configs.clone();
        app.update(|ctx| {
            ctx.subscribe_to_model(&ai_input_model, move |_, event, _| {
                if let BlocklistAIInputEvent::InputTypeChanged { config } = event {
                    recorded.borrow_mut().push(config.input_type);
                }
            });
        });

        terminal.update(&mut app, |view, ctx| {
            view.input.update(ctx, |input, ctx| {
                input.replace_buffer_content("list the files", ctx);
                input.input_enter_as_shell_command(ctx)
            });
        });

        let configs = configs.borrow();
        assert_eq!(
            configs.first(),
            Some(&InputType::Shell),
            "the submit ran with the input locked to shell"
        );
        assert_eq!(
            configs.last(),
            Some(&InputType::AI),
            "the previous configuration is restored after that one submit"
        );
    })
}

/// #826 N2: Backspace (or an arrow) typed just after the editor took input over, before focus
/// left the terminal, is applied to the editor instead of being dropped.
#[test]
fn typeahead_handoff_applies_a_key_that_beat_the_focus_change_to_the_editor() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);

        // One key per update, as in the app, where every key is its own event: the editor's
        // display map follows buffer edits through a model subscription, delivered only when
        // effects flush, and Left moves the cursor through the display map.
        let send = |app: &mut App, bytes: &'static [u8]| {
            terminal.update(app, |view, ctx| {
                view.control_sequence_on_terminal(bytes, ctx)
            });
        };
        let buffer =
            |app: &App| terminal.read(app, |view, ctx| view.input.as_ref(ctx).buffer_text(ctx));
        let cursor = |app: &App| {
            terminal.read(app, |view, ctx| {
                view.input
                    .as_ref(ctx)
                    .editor()
                    .as_ref(ctx)
                    .start_byte_index_of_last_selection(ctx)
                    .as_usize()
            })
        };

        terminal.update(&mut app, |view, ctx| {
            view.input.update(ctx, |input, ctx| {
                input.replace_buffer_content("lss", ctx);
                input
                    .editor()
                    .update(ctx, |editor, ctx| editor.move_to_buffer_end(ctx));
            });
        });
        // Not right after a hand-off: the key keeps its old meaning (dropped).
        send(&mut app, &[0x7f]);
        assert_eq!(buffer(&app), "lss");

        terminal.update(&mut app, |view, _| view.note_editor_took_over());
        send(&mut app, &[0x7f]);
        assert_eq!(buffer(&app), "ls");
        assert_eq!(cursor(&app), 2);
        send(&mut app, b"\x1b[D");
        assert_eq!(cursor(&app), 1, "Left moved the cursor");
        send(&mut app, &[0x7f]);
        assert_eq!(buffer(&app), "s");
    })
}

/// #1016: an Enter typed after a complete line that reaches the terminal just after the editor
/// took input over (CGEvent injection at ~1 ms/key beats the focus change) submits the line. It
/// used to be dropped, leaving the line unsubmitted in the editor. With nothing in the editor it
/// is still a stray Enter and does nothing.
#[test]
fn typeahead_handoff_an_enter_that_beat_the_focus_change_submits_the_editor_line() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            awaiting_typeahead_report(view);
            view.note_editor_took_over();
            // Nothing to submit: a stray Enter is ignored, the report is still awaited.
            view.keydown_on_terminal("\r", ctx);
            assert_eq!(
                view.model.lock().typeahead_handoff().state(),
                &HandoffState::AwaitingReport
            );

            view.input.update(ctx, |input, ctx| {
                input.replace_buffer_content("echo LOCAL-OK-42", ctx)
            });
            view.keydown_on_terminal("\r", ctx);
            assert!(
                matches!(
                    view.model.lock().typeahead_handoff().state(),
                    HandoffState::HoldAfterEnter { .. }
                ),
                "the Enter reached the editor's submit path instead of being dropped"
            );
        });
    })
}

/// Without the flag a key on the terminal at the prompt is still dropped.
#[test]
fn without_typeahead_handoff_a_key_on_the_terminal_at_the_prompt_is_dropped() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _flag = FeatureFlag::TypeaheadHandoff.override_enabled(false);
        let terminal = add_window_with_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            view.input
                .update(ctx, |input, ctx| input.replace_buffer_content("lss", ctx));
            view.model
                .lock()
                .typeahead_handoff_mut()
                .note_editor_took_over(Instant::now());
            view.control_sequence_on_terminal(&[0x7f], ctx);
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "lss");
        });
    })
}

/// Issue #852: a PTY hand-over to the user must pull focus off the command's AI card, or the
/// answer (a password, `[y/N]`) is typed into the card and dropped. Ordinary focus
/// reconciliation still leaves a focused AI block alone.
#[test]
fn user_takeover_overrides_ai_block_focus_guard() {
    assert!(ai_block_focus_permits_terminal_reset(false, false));
    assert!(!ai_block_focus_permits_terminal_reset(false, true));
    assert!(ai_block_focus_permits_terminal_reset(true, true));
    assert!(ai_block_focus_permits_terminal_reset(true, false));
}

/// #960: Ctrl-C / Ctrl-D always reach the pty while a subshell bootstrap is pending or has been
/// typed (even when the shell never answered, so nothing is pending); every other key stays held
/// until the stall ceiling, after which nothing is held (no automatic abort is ever written).
#[test]
fn pending_subshell_bootstrap_forwards_only_abort_keys() {
    let young = Some(std::time::Duration::from_secs(1));
    assert!(!subshell_bootstrap_key_forwarded(false, true, None));
    assert!(!subshell_bootstrap_key_forwarded(false, false, None));
    assert!(!subshell_bootstrap_key_forwarded(true, false, None));
    assert!(subshell_bootstrap_key_forwarded(true, true, None));
    // Typed but the shell never ran it: abort keys pass, others are still held.
    assert!(subshell_bootstrap_key_forwarded(false, true, young));
    assert!(!subshell_bootstrap_key_forwarded(false, false, young));
    assert!(!subshell_bootstrap_key_forwarded(true, false, young));
}

/// #1711 (owner decision 2026-11-08, #1679): a stalled subshell bootstrap never stops holding
/// typing by age. The old rule forwarded every key once the 20 s ceiling passed, into a tty that
/// still held the setup lines, so the late bootstrap read the keys as part of itself; now the
/// setup net hands the held keys back to the editor instead, and the routing rule forwards abort
/// keys only, however old the announcement.
#[test]
fn a_stalled_subshell_bootstrap_still_holds_typing_the_net_hands_it_back() {
    for age in [
        Duration::from_secs(20),
        Duration::from_secs(90),
        Duration::from_secs(600),
    ] {
        assert!(!subshell_bootstrap_key_forwarded(false, false, Some(age)));
        assert!(!subshell_bootstrap_key_forwarded(true, false, Some(age)));
        assert!(subshell_bootstrap_key_forwarded(false, true, Some(age)));
        assert!(subshell_bootstrap_key_forwarded(true, true, Some(age)));
    }
}

/// #960: `InitShell` finishes the block the first stage was typed into, so a stall after it has
/// a different active block. The fail-safe (abort keys always pass, typing held for the setup's
/// events or the net) must stay armed for as long as the subshell session is pending, and disarm
/// once the session is bootstrapped, the pane is read-only, or the pending session is gone with
/// the block.
#[test]
fn subshell_bootstrap_announcement_survives_the_initshell_block_change() {
    // Same block, nothing pending yet: armed (script typed, shell never answered).
    assert!(subshell_bootstrap_announcement_applies(
        false, false, true, false
    ));
    // Block changed by InitShell, subshell session pending: still armed (the old code lost it).
    assert!(subshell_bootstrap_announcement_applies(
        false, false, false, true
    ));
    // Block changed and no pending subshell session: the shell it was for is gone.
    assert!(!subshell_bootstrap_announcement_applies(
        false, false, false, false
    ));
    // Session bootstrapped after the block changed, or read-only: never holds. (With the block
    // unchanged, "bootstrapped" is the parent's block and says nothing about the subshell: #1014.)
    assert!(!subshell_bootstrap_announcement_applies(
        false, true, false, true
    ));
    assert!(!subshell_bootstrap_announcement_applies(
        true, false, true, true
    ));
    // Composed with the key rule (#1711): with a changed block and the session pending, typing is
    // still held however old the announcement; only abort keys pass.
    let applies = subshell_bootstrap_announcement_applies(false, false, false, true);
    let age = applies.then_some(Duration::from_secs(120));
    assert!(!subshell_bootstrap_key_forwarded(true, false, age));
    assert!(subshell_bootstrap_key_forwarded(true, true, age));
    assert!(subshell_bootstrap_key_forwarded(
        true,
        true,
        Some(std::time::Duration::from_secs(1))
    ));
}

#[test]
fn abort_keys_are_exactly_ctrl_c_and_ctrl_d() {
    assert!(is_abort_key(&[0x03]));
    assert!(is_abort_key(&[0x04]));
    assert!(!is_abort_key(b"c"));
    assert!(!is_abort_key(&[0x03, 0x03]));
    assert!(!is_abort_key(b""));
}

/// #983, #1808: typing is held while an ssh bootstrap is pending, and only an EVENT ends that: the
/// pending session going away, or its bootstrap-failed give-up marking it failed. No age does:
/// the same answer however long the session has been pending.
#[test]
fn ssh_bootstrap_swallow_is_ended_by_events_only() {
    let sid = SessionId::from(4242);
    let other = SessionId::from(4343);

    // No pending session: nothing is held on its behalf.
    assert!(!ssh_bootstrap_swallow_active(None, None));
    assert!(!ssh_bootstrap_swallow_active(None, Some(sid)));

    // A pending session holds, however long it has been pending (the function takes no time).
    assert!(ssh_bootstrap_swallow_active(Some(sid), None));
    assert!(ssh_bootstrap_swallow_active(Some(sid), Some(other)));

    // Its failure give-up fired: it no longer holds.
    assert!(!ssh_bootstrap_swallow_active(Some(sid), Some(sid)));

    // A different (new) pending session is not covered by the old failure mark.
    assert!(ssh_bootstrap_swallow_active(Some(other), Some(sid)));
}

/// #1808 (byte trace for the removed 15 s swallow ceiling): while the remote bootstrap is pending
/// the typed line is held byte for byte, in order, with every later key joining it; nothing
/// reaches the pty and nothing reaches the editor. Only the bootstrap-failed hand-back (or the
/// remote prompt) ends the hold.
#[test]
fn ssh_keys_typed_during_a_pending_bootstrap_stay_held_in_order_and_unwritten() {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_all_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            assert_eq!(view.ssh_held_bytes(), "echo hi\r".len());
            // Keep typing while the bootstrap is still pending: each key joins the hold.
            for key in "ls".chars() {
                view.typed_characters_on_terminal(&key.to_string(), ctx);
            }
            assert!(view.ssh_typeahead_holding);
            assert_eq!(
                view.ssh_held_bytes(),
                "echo hi\rls".len(),
                "no key lost, none doubled"
            );
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "");
        });
        assert!(
            pty_writes.borrow().is_empty(),
            "nothing was written mid-bootstrap: {:?}",
            pty_writes.borrow()
        );
    })
}

/// #988: with a command (e.g. `ksu`) running, clicking an earlier agent response must not be
/// refused with the "Cannot enter agent mode while a command is running" toast; it routes to the
/// read-only viewer action instead, and the running pane does not enter the agent view.
#[test]
fn long_running_click_on_agent_response_routes_to_read_only_viewer_not_toast() {
    use crate::ai::blocklist::agent_view::EnterAgentViewError;
    use crate::workspace::WorkspaceAction;

    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);
        let terminal = add_window_with_terminal(&mut app, None);

        let conversation_id = terminal.update(&mut app, |view, ctx| {
            BlocklistAIHistoryModel::handle(ctx).update(ctx, |history_model, ctx| {
                history_model.start_new_conversation(view.view_id, false, false, ctx)
            })
        });

        terminal.update(&mut app, |view, ctx| {
            view.model
                .lock()
                .simulate_long_running_block("ksu", "running");

            // The real controller still refuses to enter in-pane...
            let error = view
                .agent_view_controller
                .update(ctx, |controller, ctx| {
                    controller.try_enter_agent_view(
                        Some(conversation_id),
                        AgentViewEntryOrigin::AgentViewBlock,
                        ctx,
                    )
                })
                .expect_err("entering agent view must be refused while a command runs");
            assert_eq!(error, EnterAgentViewError::LongRunningCommand);

            // ...and a click on an agent entry card turns that refusal into the viewer action.
            let action = super::agent_view::long_running_entry_viewer_action(
                error,
                AgentViewEntryOrigin::AgentViewBlock,
                conversation_id,
            );
            assert!(matches!(
                action,
                Some(WorkspaceAction::OpenLiveConversationReadOnlyViewer { conversation_id: id })
                    if id == conversation_id
            ));

            // Programmatic origins and other errors keep their toast: never redirected silently.
            for origin in [
                AgentViewEntryOrigin::AutoFollowUp,
                AgentViewEntryOrigin::Keybinding,
                AgentViewEntryOrigin::LongRunningCommand,
            ] {
                assert!(
                    super::agent_view::long_running_entry_viewer_action(
                        error,
                        origin,
                        conversation_id
                    )
                    .is_none()
                );
            }
            assert!(
                super::agent_view::long_running_entry_viewer_action(
                    EnterAgentViewError::AlreadyInAgentView,
                    AgentViewEntryOrigin::AgentViewBlock,
                    conversation_id,
                )
                .is_none()
            );

            // The running pane did not enter the agent view and still has its command running.
            assert!(
                !view
                    .agent_view_controller
                    .as_ref(ctx)
                    .agent_view_state()
                    .is_active()
            );
            assert!(
                view.model
                    .lock()
                    .block_list()
                    .active_block()
                    .is_active_and_long_running()
            );
        });
    });
}

/// #992: the read-only viewer never enters the conversation's agent view, so its AI blocks must
/// not be scoped to it; otherwise the terminal transcript scope hides every one of them and the
/// pane renders blank.
#[test]
fn read_only_view_of_live_conversation_renders_its_ai_blocks() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });

        let live = add_window_with_terminal(&mut app, None);
        let conversation_id = live.update(&mut app, |view, ctx| {
            let (conversation_id, ..) = append_exchange_and_handle_event(
                view,
                AIAgentInput::UserQuery {
                    query: "earlier question".to_owned(),
                    context: Default::default(),
                    static_query_type: None,
                    referenced_attachments: Default::default(),
                    user_query_mode: UserQueryMode::Normal,
                    running_command: None,
                    intended_agent: None,
                },
                ctx,
            );
            conversation_id
        });
        let snapshot = BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
            history
                .conversation(&conversation_id)
                .expect("live conversation should exist")
                .clone()
        });

        let viewer = add_window_with_terminal(&mut app, None);
        viewer.update(&mut app, |view, ctx| {
            view.restore_conversations_on_view_creation(
                ConversationRestorationInNewPaneType::Historical {
                    conversation: snapshot,
                    should_use_live_appearance: true,
                    ambient_agent_task_id: None,
                    read_only_view_of_live: true,
                },
                ctx,
            );
        });

        viewer.read(&app, |view, _| {
            let ai_view_ids: Vec<_> = view
                .rich_content_views
                .iter()
                .filter(|rich_content| {
                    rich_content
                        .ai_block_metadata()
                        .is_some_and(|metadata| metadata.conversation_id == conversation_id)
                })
                .map(|rich_content| rich_content.view_id())
                .collect();
            assert!(!ai_view_ids.is_empty());
            let model = view.model.lock();
            let mut visible = 0;
            for item in model
                .block_list()
                .block_heights()
                .cursor::<TotalIndex, ()>()
            {
                if let crate::terminal::model::blocks::BlockHeightItem::RichContent(item) = item {
                    if ai_view_ids.contains(&item.view_id) {
                        assert!(!item.should_hide, "viewer AI block is hidden");
                        visible += 1;
                    }
                }
            }
            assert_eq!(visible, ai_view_ids.len());
        });
    });
}

/// #992: the AI block view itself hides when there is no active agent view and it is not a
/// passive suggestion (`AIBlock::is_hidden`). A read-only view of a live conversation never
/// enters an agent view, so its blocks rendered as empty zero-height elements and the pane was
/// blank even though the blocks were in the block list and not scoped away. They must render.
#[test]
fn read_only_view_of_live_conversation_ai_blocks_are_not_hidden_by_the_ai_block_view() {
    use crate::terminal::model::terminal_model::ConversationTranscriptViewerStatus;

    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });

        let live = add_window_with_terminal(&mut app, None);
        let conversation_id = live.update(&mut app, |view, ctx| {
            let (conversation_id, ..) = append_exchange_and_handle_event(
                view,
                AIAgentInput::UserQuery {
                    query: "earlier question".to_owned(),
                    context: Default::default(),
                    static_query_type: None,
                    referenced_attachments: Default::default(),
                    user_query_mode: UserQueryMode::Normal,
                    running_command: None,
                    intended_agent: None,
                },
                ctx,
            );
            conversation_id
        });
        let snapshot = BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
            history
                .conversation(&conversation_id)
                .expect("live conversation should exist")
                .clone()
        });

        let viewer = add_window_with_terminal(&mut app, None);
        viewer.update(&mut app, |view, ctx| {
            view.restore_conversations_on_view_creation(
                ConversationRestorationInNewPaneType::Historical {
                    conversation: snapshot,
                    should_use_live_appearance: true,
                    ambient_agent_task_id: None,
                    read_only_view_of_live: true,
                },
                ctx,
            );
        });
        let ai_block = |view: &TerminalView| {
            view.rich_content_views
                .iter()
                .find_map(|rich_content| {
                    rich_content
                        .ai_block_metadata()
                        .filter(|metadata| metadata.conversation_id == conversation_id)
                        .map(|metadata| metadata.ai_block_handle.clone())
                })
                .expect("the viewer restored an AI block")
        };

        // Control: the same pane without the viewer status is an ordinary terminal with no active
        // agent view, where the block view hides itself.
        let handle = viewer.read(&app, |view, _| ai_block(view));
        handle.read(&app, |block, ctx| {
            assert!(block.is_hidden(ctx), "control: no agent view, not passive");
        });

        viewer.update(&mut app, |view, _| {
            view.model
                .lock()
                .set_conversation_transcript_viewer_status(Some(
                    ConversationTranscriptViewerStatus::ViewingLiveConversationReadOnly(
                        conversation_id,
                    ),
                ));
        });
        // `is_hidden` reads the history model, not the (lock-holding) terminal model.
        let viewer_id = viewer.id();
        BlocklistAIHistoryModel::handle(&app).update(&mut app, |history, _| {
            history.mark_terminal_view_as_read_only_live_viewer(viewer_id, conversation_id);
        });
        // Regression: callers hold the terminal model lock while asking; this must not deadlock.
        viewer.update(&mut app, |view, ctx| {
            let _model_guard = view.model.lock();
            assert!(!handle.as_ref(ctx).is_hidden(ctx));
        });
        handle.read(&app, |block, ctx| {
            assert!(
                !block.is_hidden(ctx),
                "the read-only viewer's AI block must render"
            );
        });

        // A viewer of a different conversation does not unhide this one.
        viewer.update(&mut app, |view, _| {
            view.model
                .lock()
                .set_conversation_transcript_viewer_status(Some(
                    ConversationTranscriptViewerStatus::ViewingLiveConversationReadOnly(
                        AIConversationId::new(),
                    ),
                ));
        });
        BlocklistAIHistoryModel::handle(&app).update(&mut app, |history, _| {
            history.mark_terminal_view_as_read_only_live_viewer(viewer_id, AIConversationId::new());
        });
        handle.read(&app, |block, ctx| {
            assert!(block.is_hidden(ctx));
        });
    });
}

/// #988: a read-only view of a conversation that is live in another pane must not register a
/// second live copy, take over liveness, or overwrite the live `AIConversation`.
#[test]
fn read_only_view_of_live_conversation_does_not_register_a_second_live_copy() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });

        let live = add_window_with_terminal(&mut app, None);
        let (conversation_id, live_view_id) = live.update(&mut app, |view, ctx| {
            let (conversation_id, ..) = append_exchange_and_handle_event(
                view,
                AIAgentInput::UserQuery {
                    query: "earlier question".to_owned(),
                    context: Default::default(),
                    static_query_type: None,
                    referenced_attachments: Default::default(),
                    user_query_mode: UserQueryMode::Normal,
                    running_command: None,
                    intended_agent: None,
                },
                ctx,
            );
            // The live pane is showing the conversation in its agent view.
            view.enter_agent_view_for_conversation(
                None,
                AgentViewEntryOrigin::AgentViewBlock,
                conversation_id,
                ctx,
            );
            (conversation_id, view.view_id)
        });
        live.read(&app, |view, ctx| {
            assert_eq!(
                view.active_conversation_id(ctx),
                Some(conversation_id),
                "setup: the live pane starts in the conversation's agent view"
            );
        });
        let live_snapshot = BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
            history
                .conversation(&conversation_id)
                .expect("live conversation should exist")
                .clone()
        });
        let exchanges_before = live_snapshot.all_exchanges().len();

        let viewer = add_window_with_terminal(&mut app, None);
        let viewer_view_id = viewer.update(&mut app, |view, ctx| {
            view.restore_conversations_on_view_creation(
                ConversationRestorationInNewPaneType::Historical {
                    conversation: live_snapshot,
                    should_use_live_appearance: true,
                    ambient_agent_task_id: None,
                    read_only_view_of_live: true,
                },
                ctx,
            );
            view.view_id
        });

        BlocklistAIHistoryModel::handle(&app).read(&app, |history, _| {
            assert_eq!(
                history.live_owner_terminal_view(conversation_id),
                Some(live_view_id),
                "the original pane must still own the live conversation"
            );
            assert_eq!(
                history
                    .all_live_conversations_for_terminal_view(viewer_view_id)
                    .count(),
                0,
                "the read-only view must not register a live copy"
            );
            assert_eq!(
                history
                    .conversation(&conversation_id)
                    .expect("live conversation should still exist")
                    .all_exchanges()
                    .len(),
                exchanges_before,
                "the live conversation must not be overwritten"
            );
        });
        live.read(&app, |view, ctx| {
            assert_eq!(view.active_conversation_id(ctx), Some(conversation_id));
        });
        // It still renders the earlier response from the shared conversation.
        viewer.read(&app, |view, _| {
            assert!(view.rich_content_views.iter().any(|rich_content| {
                rich_content
                    .ai_block_metadata()
                    .is_some_and(|metadata| metadata.conversation_id == conversation_id)
            }));
        });
    });
}

