/// #983: the gate's pure transitions. ssh owning the tty ends the pre-ownership hold (#1611,
/// #1612, #1621; nothing read from the screen does), a clean block end keeps holding for the
/// bootstrap grace, a failure or a session that came up releases.
#[test]
fn ssh_connect_gate_transitions() {
    let t0 = Instant::now();
    let mut gate = SshConnectGate::new(t0);
    assert_eq!(
        gate.tty_owned,
        crate::terminal::input_queue::TTY_OWNED_AT_ARM
    );
    assert!(gate.drops_keys(false));
    assert!(!gate.drops_keys(true), "full-screen programs never hold");
    assert!(!gate.should_release(t0, false));
    gate.tty_owned = true;
    assert!(
        !gate.drops_keys(false),
        "ssh owns the tty: its prompts get their answers"
    );
    // A clean block end of an unmanaged / short session (no remote ever announced) releases.
    let mut unmanaged = SshConnectGate::new(t0);
    unmanaged.note_block_completed(t0, true);
    assert!(!unmanaged.drops_keys(false));
    assert!(unmanaged.should_release(t0, false));
    // A clean block end of a managed remote re-holds (the bootstrap is coming) even after
    // ssh owned the tty.
    gate.managed = true;
    gate.note_block_completed(t0, true);
    assert!(gate.drops_keys(false));
    assert!(!gate.should_release(t0 + Duration::from_secs(1), false));
    assert!(gate.should_release(t0 + SSH_CONNECT_POST_BLOCK_GRACE, false));
    // Announced session, then gone (bootstrapped, or exited): held until the remote shell's
    // first prompt (#1085). Releasing at `Bootstrapped` let keys typed while the bootstrap was
    // still finishing reach the remote tty as typeahead, which came back split at the prompt.
    let mut gate = SshConnectGate::new(t0);
    assert!(!gate.should_release(t0, true));
    assert!(!gate.should_release(t0, false));
    gate.tty_owned = true;
    assert!(
        gate.drops_keys(false),
        "the bootstrap tail drops keys even after ssh owned the tty"
    );
    assert!(!gate.drops_keys(true), "full-screen programs never hold");
    gate.first_prompt_seen = true;
    assert!(gate.should_release(t0, false));
    // A remote whose first prompt never comes is bounded by the first-prompt grace, counted from
    // the end of the bootstrap.
    let mut gate = SshConnectGate::new(t0);
    let bootstrapped = t0 + Duration::from_millis(500);
    assert!(!gate.should_release(t0, true));
    assert!(!gate.should_release(bootstrapped, false));
    assert!(!gate.should_release(bootstrapped + Duration::from_secs(1), false));
    assert!(gate.should_release(bootstrapped + SSH_CONNECT_FIRST_PROMPT_GRACE, false));
    // Failure releases at once; so does the ceiling.
    let mut gate = SshConnectGate::new(t0);
    gate.note_block_completed(t0, false);
    assert!(gate.should_release(t0, false));
    let mut gate = SshConnectGate::new(t0);
    assert!(gate.should_release(t0 + SSH_CONNECT_NO_PROBE_GIVE_UP, false));
}

/// #1809: where the tty-read probe works there is no clock on the connect window at all: no
/// ceiling release and no ceiling deadline, however old the window is. Only events (and the
/// event-armed post-bootstrap / post-block graces) end it. Without a probe the hand-back-only net
/// stays (`SSH_CONNECT_NO_PROBE_GIVE_UP`).
#[test]
fn ssh_gate_with_a_tty_read_probe_has_no_clock() {
    let t0 = Instant::now();
    let long_after = t0 + Duration::from_secs(3600);
    let mut gate = SshConnectGate::new(t0);
    gate.tty_read_detectable = true;
    assert!(!gate.past_ceiling(long_after));
    assert!(!gate.should_release(long_after, false));
    assert_eq!(gate.give_up_deadline(false), None);
    assert_eq!(gate.give_up_deadline(true), None);
    // The graces are armed by events and still bound the window.
    gate.block_done_at = Some(t0 + Duration::from_secs(1));
    assert_eq!(
        gate.give_up_deadline(false),
        Some(t0 + Duration::from_secs(1) + SSH_CONNECT_POST_BLOCK_GRACE)
    );
    // The same window without a probe keeps the net.
    let mut gate = SshConnectGate::new(t0);
    gate.tty_read_detectable = false;
    assert!(gate.past_ceiling(t0 + SSH_CONNECT_NO_PROBE_GIVE_UP));
    assert_eq!(
        gate.give_up_deadline(false),
        Some(t0 + SSH_CONNECT_NO_PROBE_GIVE_UP)
    );
}

#[test]
fn visible_text_ignores_whitespace_and_controls() {
    assert!(!output_has_visible_text(""));
    assert!(!output_has_visible_text("\r\n\n \t\u{7}\u{1b}"));
    assert!(output_has_visible_text("\r\nPassword:"));
}

fn submit_command(view: &mut TerminalView, command: &str, ctx: &mut ViewContext<TerminalView>) {
    let session_id = view
        .active_block_session_id()
        .unwrap_or_else(|| SessionId::from(9001));
    view.handle_input_event(
        &InputEvent::ExecuteCommand(Box::new(ExecuteCommandEvent {
            command: command.to_owned(),
            session_id,
            workflow_id: None,
            workflow_command: None,
            should_add_command_to_history: true,
            source: CommandExecutionSource::User,
        })),
        ctx,
    );
}

/// #983 window 1: keys typed right after Enter, before the shell's preexec has set the pending
/// ssh state (and inside the first 50 ms, when the block is not yet "long running"), must be
/// dropped whole, not written to the tty or the editor.
#[test]
fn ssh_keys_before_pending_state_is_set_are_dropped_whole() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        // Before login a Ctrl-C reaches ssh as SIGINT to the pty's foreground group (#1001), not
        // as a written byte; the other interrupt keys are still written.
        let sigints = Rc::new(RefCell::new(0usize));
        let counter = sigints.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if matches!(event, Event::SigintForegroundToPty) {
                    *counter.borrow_mut() += 1;
                }
            });
        });
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            submit_command(view, "ssh host", ctx);
            assert!(!view.has_pending_ssh_command(), "preexec has not run yet");
            view.typed_characters_on_terminal("echo typed-", ctx);
            view.typed_characters_on_terminal("during-connect", ctx);
            view.keydown_on_terminal("\r", ctx);
            assert!(view.ssh_typeahead_holding, "the keys are held (#1292)");
            assert_eq!(view.ssh_held_bytes(), 26);
            assert_eq!(
                view.input.as_ref(ctx).buffer_text(ctx),
                "",
                "held text must not land in the editor either"
            );
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "");
            // #1111: Ctrl-D is NOT written into a connect that is still silent (see
            // `ssh_ctrl_d_is_held_during_a_silent_connect`); the other interrupt keys are.
            for key in ["\u{3}", "\u{4}", "\u{1a}", "\u{1c}"] {
                view.keydown_on_terminal(key, ctx);
            }
        });
        let writes = pty_writes.borrow();
        assert!(
            !writes.iter().any(|w| w.as_slice() == b"\x04"),
            "Ctrl-D must be held during the silent connect: {writes:?}"
        );
        assert!(
            !writes.iter().any(|w| w.as_slice() == b"echo typed-"
                || w.as_slice() == b"during-connect"
                || w.as_slice() == b"\r"),
            "typed text must not reach the tty: {writes:?}"
        );
        assert!(
            *sigints.borrow() == 1 || writes.iter().any(|w| w.as_slice() == b"\x03"),
            "Ctrl-C must reach ssh while armed (as SIGINT or the byte): {writes:?}"
        );
        for key in [&b"\x1a"[..], b"\x1c"] {
            assert!(
                writes.iter().any(|w| w.as_slice() == key),
                "interrupt key {key:?} must reach the pty while armed: {writes:?}"
            );
        }
    })
}

/// #983 window 2, redone by #1611/#1612/#1621: output of ANY shape (hooks, a newline echo, a
/// password prompt) does not open the gate; nothing about the connect is read from the screen.
/// Typing is held whole until ssh owns the tty, then delivered to it once, in order, and later
/// keys pass straight through. Two held Enters: the drain yields after the first one it writes
/// (#1421, `Host::yield_after`: an Enter may have submitted a command whose gate is armed by the
/// event it emits) and the waker continues it on the next turn, so the test gives it those turns
/// before judging, as production does; a live key typed while the drain is yielded queues behind
/// the held ones (FIFO) and goes out with them.
#[test]
fn ssh_output_of_any_shape_does_not_open_the_gate_ownership_does() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "\r\n\x1b[0m\x1b]0;title\x07\r\n");
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            view.typed_characters_on_terminal("echo hi", ctx);
            view.keydown_on_terminal("\r", ctx);
        });
        assert!(pty_writes.borrow().is_empty(), "{:?}", pty_writes.borrow());
        // A prompt's text is output like any other: still held.
        terminal.update(&mut app, |view, ctx| {
            view.model.lock().process_bytes("host's password: ");
            view.handle_terminal_wakeup(crate::terminal::event_listener::Wakeup::Output, ctx);
            view.keydown_on_terminal("\r", ctx);
            assert!(view.ssh_typeahead_holding, "output opens nothing");
        });
        assert!(pty_writes.borrow().is_empty(), "{:?}", pty_writes.borrow());
        // ssh owns the tty: the held keys go to it, in order, and the next key passes live.
        terminal.update(&mut app, |view, ctx| {
            ssh_tty_owned_for_test(view, ctx);
            assert!(!view.ssh_typeahead_holding);
            assert!(view.ssh_held_is_empty());
            view.keydown_on_terminal("\r", ctx);
        });
        // The yielded drain's waker runs on a later turn (#1421); nothing else delivers it.
        crate::test_util::wait_for(|| {
            terminal.read(&app, |view, _| ssh_queue_is_idle(view))
                && pty_writes.borrow().iter().flatten().count() >= b"echo hi\r\r\r".len()
        })
        .await;
        terminal.read(&app, |view, _| {
            assert!(ssh_queue_is_idle(view), "nothing left queued");
        });
        let written: Vec<u8> = pty_writes.borrow().iter().flatten().copied().collect();
        assert_eq!(written, b"echo hi\r\r\r", "once, in typed order, then live");
    })
}

/// Simulates the ssh hook the managed (wrapped) ssh emits during the ssh block: the model keeps a
/// pending legacy ssh session until the remote's InitShell consumes it.
fn simulate_ssh_hook(view: &mut TerminalView) {
    crate::terminal::model::ansi::Handler::ssh(
        &mut *view.model.lock(),
        crate::terminal::model::ansi::SSHValue {
            remote_shell: "bash".to_owned(),
            remote_session_id: Some(167303092612202),
            ..Default::default()
        },
    );
}

/// #983 window 3 (managed): the ssh block ends (remote shell's first precmd) before the remote
/// session is registered; typing in that gap, even with MOTD text already printed, is dropped
/// whole. The ssh hook seen during the block marks the remote as managed.
#[test]
fn ssh_keys_after_ssh_block_ends_before_remote_session_are_dropped() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            submit_command(view, "ssh host", ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "Welcome to Ubuntu\r\n");
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            simulate_ssh_hook(view);
            // The event handler observes the hook while the ssh block still runs.
            view.refresh_ssh_connect_gate();
            view.ssh_observe(ctx);
            assert!(view.ssh_connect_gate.as_ref().is_some_and(|g| g.managed));
            // ssh owned the tty (nothing was held): the gate is open for live keys...
            ssh_tty_owned_for_test(view, ctx);
            assert!(!view.ssh_connect_gate_drops_keys());
            // ...until the ssh block completes cleanly on the managed remote (the pending ssh
            // state is cleared with it): the bootstrap is coming, so typing is held again.
            let armed = view.model.lock().active_block_id().clone();
            view.apply_block_completed_to_ssh_gate(&armed, 0);
            view.warpify_state.clear_pending_ssh_host();
            view.typed_characters_on_terminal("echo hi", ctx);
            view.keydown_on_terminal("\r", ctx);
            assert!(view.ssh_typeahead_holding);
            assert!(!view.ssh_held_is_empty());
        });
        assert!(pty_writes.borrow().is_empty(), "{:?}", pty_writes.borrow());
    })
}

/// A pane whose `ssh host` is connecting: the remote shell announced itself (pending session, no
/// `Bootstrapped` yet) and "echo hi" + Enter were typed meanwhile, so they are held (#1494).
fn ssh_pane_with_held_typeahead_for_test(
    view: &mut TerminalView,
    ctx: &mut ViewContext<TerminalView>,
) {
    register_local_session_for_ssh_test(view, ctx);
    submit_command(view, "ssh host", ctx);
    view.model
        .lock()
        .simulate_long_running_block("ssh host", "");
    view.warpify_state
        .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
    simulate_ssh_hook(view);
    view.refresh_ssh_connect_gate();
    // The model events (the ssh hook, InitShell) are the edges that feed the ssh phase in `table`
    // mode; the test drives the gate directly, so it feeds what those events would.
    view.ssh_observe(ctx);
    view.model.lock().init_shell(InitShellValue {
        pid: None,
        session_id: SessionId::from(167303092612202),
        shell: "bash".to_owned(),
        user: "user".to_owned(),
        hostname: "host".to_owned(),
        ..Default::default()
    });
    assert!(view.refresh_ssh_connect_gate());
    view.ssh_observe(ctx);
    view.typed_characters_on_terminal("echo hi", ctx);
    view.keydown_on_terminal("\r", ctx);
    assert!(view.ssh_typeahead_holding, "the keys are held (#1292)");
    assert!(!view.ssh_held_is_empty());
}

/// #1494: the ssh bootstrap timed out with typing held and the remote shell is alive at a
/// non-bootstrapped prompt. The held keys are WRITTEN TO THE PTY in typed order, the Enter in its
/// place, exactly what a plain terminal would have sent all along; Phosphor adds no command of
/// its own (no ` stty sane`, #1815), nothing is put into or kept for the editor, the editor
/// submits nothing, and the write is not marked as a committed hand-over.
///
/// Expectation history (re-decided by the owner, never weakened): #1577 (2026-11-03) handed the
/// held text back and wrote nothing, which this test expected under the name
/// `ssh_bootstrap_failure_hands_held_typeahead_back_without_stty_sane`; owner decision
/// 2026-11-09 (#1996, decision 2 of the follow-up) makes this timer write the keys to the pty
/// like every other give-up of a hold for the shell.
#[test]
fn ssh_bootstrap_failure_writes_held_typeahead_to_the_pty_without_stty_sane() {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_all_pty_writes(&mut app, &terminal);
        let executed = count_executed_commands(&mut app, &terminal);
        // The pane's own `ssh host` submit is an ExecuteCommand too; only what runs after it
        // (the held `echo hi` + Enter, a bootstrap line) counts.
        terminal.update(&mut app, |view, ctx| {
            ssh_pane_with_held_typeahead_for_test(view, ctx);
        });
        // Read between updates: the view's events are delivered once an update has ended.
        let ran_during_setup = *executed.borrow();
        terminal.update(&mut app, |view, ctx| {
            view.model
                .lock()
                .process_bytes("stty -echo; eval \"$(cat)\"\r\n");
            view.model
                .lock()
                .block_list()
                .active_block()
                .interactive_latch()
                .force(true);
            assert!(view.is_long_running(), "the bootstrap block is running");
            view.on_bootstrap_failed_timer_complete((), ctx);
            assert!(!view.ssh_typeahead_holding);
            assert!(view.ssh_held_is_empty());
            // Nothing comes back: not into the editor, and not kept for it until the ssh block
            // ends.
            let input = view.input.as_ref(ctx);
            let kept = input.handed_back_text_for_test().map(str::to_owned);
            let shown = input.buffer_text(ctx);
            assert!(
                kept.is_none() && shown.is_empty(),
                "the held text went to the pty, not back: kept={kept:?} \
                     shown={shown:?}"
            );
            assert!(
                !view
                    .model
                    .lock()
                    .typeahead_handoff()
                    .committed_delivery_pending(),
                "a give-up's write is not a committed hand-over delivery"
            );
        });
        let text = String::from_utf8_lossy(&pty_writes.borrow().concat()).into_owned();
        assert_eq!(
            text, "echo hi\r",
            "the held keys, in typed order, once, and nothing else (no `stty sane`)"
        );
        assert_eq!(
            *executed.borrow(),
            ran_during_setup,
            "the editor submitted nothing after the pane's own `ssh host`"
        );
    })
}

/// #1566 (r18cz Linux, 1 in 9 connects): the 7 s bootstrap give-up timer expired 20 ms after the
/// remote's bootstrap `Precmd` and 40 ms before `Bootstrapped`. The #1494 failure path then handed
/// the held line back / `stty sane`d the tty under the bootstrap, and the line was lost or landed
/// in the wrong place. A session that already showed its bootstrap prompt is progressing: the
/// timer waits (once, logged), `Bootstrapped` and the first remote prompt deliver the line to the
/// pty exactly once, and the editor stays empty.
#[test]
fn ssh_bootstrap_timer_racing_the_bootstrap_precmd_does_not_fail_the_session() {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        let remote_session = SessionId::from(167303092612202);
        terminal.update(&mut app, |view, ctx| {
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            // The bootstrap script's own prompt, while the session is still pending.
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            assert!(
                view.ssh_typeahead_holding && !view.ssh_held_is_empty(),
                "still held after the bootstrap precmd"
            );
            // The give-up timer expires in the window before `Bootstrapped`.
            view.on_bootstrap_failed_timer_complete((), ctx);
            assert!(
                view.ssh_typeahead_holding && !view.ssh_held_is_empty(),
                "the timer must not fail a progressing session"
            );
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "");
            // In-update recorder read, always empty here: the keys are still held (above) and
            // the final read has the line once, no `stty sane`.
            assert!(
                pty_writes.borrow().is_empty(),
                "no stty sane, no keys: {:?}",
                pty_writes.borrow()
            );
            // `Bootstrapped`, then the remote's first prompt.
            view.model.lock().bootstrapped(BootstrappedValue {
                shell: "bash".to_owned(),
                ..Default::default()
            });
            view.handle_terminal_event(
                &ModelEvent::Handler(AnsiHandlerEvent::Bootstrapped {
                    session_id: remote_session,
                    is_subshell: false,
                }),
                ctx,
            );
            view.model.lock().simulate_long_running_block("sleep 5", "");
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            assert!(view.ssh_held_is_empty(), "handed over");
            assert_eq!(
                view.input.as_ref(ctx).buffer_text(ctx),
                "",
                "the line went to the pty, not the editor"
            );
        });
        let text = String::from_utf8_lossy(&pty_writes.borrow().concat()).into_owned();
        assert_eq!(text.matches("echo hi").count(), 1, "once: {text:?}");
        assert!(!text.contains("stty sane"), "{text:?}");
    })
}

/// #1566 follow-up (r18cz Linux): a give-up timer armed for an earlier connect expired ~1 s into
/// the next one and failed it. Connect A arms, connect B (a new pending session) starts
/// bootstrapping with keys held, A's timer fires: it is a no-op -- nothing written, keys still
/// held, no `stty sane` -- and B then completes normally with the keys reaching the pty once.
#[test]
fn stale_bootstrap_timer_from_an_earlier_connect_does_not_fail_a_later_one() {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        let remote_session = SessionId::from(167303092612202);
        terminal.update(&mut app, |view, ctx| {
            // Connect A: its give-up timer is armed (the identity it carries is captured).
            let stale_arm = BootstrapTimerArm {
                generation: view.bootstrap_timer_generation,
                session: Some(SessionId::from(167303092612201)),
            };
            // Connect B: a different pending session, keys held.
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            assert!(view.ssh_typeahead_holding && !view.ssh_held_is_empty());
            // A's timer expires while B bootstraps.
            view.on_bootstrap_timer_fired(stale_arm, ctx);
            assert!(
                view.ssh_typeahead_holding && !view.ssh_held_is_empty(),
                "a stale timer must not act on a later connect"
            );
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "");
            // In-update recorder read, always empty here: the keys are still held (above) and
            // the final read has the line once, no `stty sane`.
            assert!(
                pty_writes.borrow().is_empty(),
                "no stty sane, no keys: {:?}",
                pty_writes.borrow()
            );
            // B completes normally.
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            view.model.lock().bootstrapped(BootstrappedValue {
                shell: "bash".to_owned(),
                ..Default::default()
            });
            view.handle_terminal_event(
                &ModelEvent::Handler(AnsiHandlerEvent::Bootstrapped {
                    session_id: remote_session,
                    is_subshell: false,
                }),
                ctx,
            );
            view.model.lock().simulate_long_running_block("sleep 5", "");
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            assert!(view.ssh_held_is_empty(), "handed over");
        });
        let text = String::from_utf8_lossy(&pty_writes.borrow().concat()).into_owned();
        assert_eq!(text.matches("echo hi").count(), 1, "once: {text:?}");
        assert!(!text.contains("stty sane"), "{text:?}");
    })
}

/// What [`bootstrap_give_up_under_the_helper_question`] saw.
struct HelperQuestionGiveUp {
    /// The session was judged failed by the give-up that expired while the question was up.
    failed_under_question: bool,
    /// pty writes made by that expiry.
    writes_under_question: usize,
    /// The question took the give-up off the clock.
    paused_under_question: bool,
    /// A give-up was armed afresh when the question was answered.
    armed_at_answer: bool,
    /// That one, expiring with no `Bootstrapped`, judged the session failed.
    failed_after_answer: bool,
}

/// #2127: an ssh session whose remote shell sent `InitShell`, with a line typed during the
/// connect held, the give-up armed as the `SSH` hook arms it, and then the app's own "install
/// the remote helper?" question shown. The give-up armed before the question expires while it
/// is still up (a person takes longer than 7 s to answer), the question is answered ("continue
/// without"), and the give-up that is current after the answer expires too.
fn bootstrap_give_up_under_the_helper_question(switch_on: bool) -> HelperQuestionGiveUp {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_all_pty_writes(&mut app, &terminal);
        let remote_session = SessionId::from(167303092612202);
        let armed_before_question = terminal.update(&mut app, |view, ctx| {
            view.bootstrap_give_up_pauses_for_helper_question = switch_on;
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            assert_eq!(
                view.model.lock().pending_session_id(),
                Some(remote_session),
                "precondition: the remote session is the pending one"
            );
            // What `ModelEvent::SSH` does for a bash remote.
            view.start_bootstrap_timer(BOOTSTRAP_FAILED_DURATION, ctx);
            let arm = BootstrapTimerArm {
                generation: view.bootstrap_timer_generation,
                session: Some(remote_session),
            };
            // No helper on the host and `always_ask`: the app asks and holds the bootstrap.
            view.show_ssh_remote_server_choice_block(remote_session, ctx);
            assert!(view.ssh_helper_question_showing());
            arm
        });
        let writes_before = pty_writes.borrow().len();
        // 7 s pass with the question still on screen.
        let (failed_under_question, paused_under_question, generation_under_question) = terminal
            .update(&mut app, |view, ctx| {
                view.on_bootstrap_timer_fired(armed_before_question, ctx);
                (
                    view.ssh_bootstrap_failed_session == Some(remote_session),
                    view.bootstrap_give_up_paused_for_helper_question == Some(remote_session),
                    view.bootstrap_timer_generation,
                )
            });
        let writes_under_question = pty_writes.borrow().len() - writes_before;
        // The answer: "continue without".
        let card = terminal
            .read(&app, |view, _| view.active_ssh_remote_server_choice_block())
            .expect("the question is still showing");
        card.update(&mut app, |_, ctx| {
            ctx.emit(SshRemoteServerChoiceViewEvent::Skip { remember: false });
        });
        let (armed_at_answer, failed_after_answer) = terminal.update(&mut app, |view, ctx| {
            assert!(
                !view.ssh_helper_question_showing(),
                "the answer takes the question off the screen"
            );
            assert_eq!(
                view.bootstrap_give_up_paused_for_helper_question, None,
                "a pause never outlives its question"
            );
            let armed_at_answer = view.bootstrap_timer_generation != generation_under_question;
            // No `Bootstrapped` follows: the give-up that is current now expires.
            let arm = BootstrapTimerArm {
                generation: view.bootstrap_timer_generation,
                session: view.model.lock().pending_session_id(),
            };
            view.on_bootstrap_timer_fired(arm, ctx);
            (
                armed_at_answer,
                view.ssh_bootstrap_failed_session == Some(remote_session),
            )
        });
        HelperQuestionGiveUp {
            failed_under_question,
            writes_under_question,
            paused_under_question,
            armed_at_answer,
            failed_after_answer,
        }
    })
}

/// #2127: the bootstrap give-up is a net for a bootstrap that never completes. While the app's
/// own remote-helper question waits for a person the bootstrap has not even been written, so a
/// give-up that expires then judges nothing: the session is not marked failed and not a byte is
/// written to the pty (before #2127 the held line was written to the remote shell's raw,
/// unbootstrapped prompt and the session was marked failed, for a wait the app itself caused).
/// The answer arms the give-up afresh, and it still judges a bootstrap that then never comes.
#[test]
fn bootstrap_give_up_does_not_judge_a_session_waiting_for_the_helper_answer() {
    let seen = bootstrap_give_up_under_the_helper_question(true);
    assert!(
        seen.paused_under_question,
        "showing the question takes the give-up off the clock"
    );
    assert!(
        !seen.failed_under_question,
        "a session waiting for the user's answer is not a failed bootstrap"
    );
    assert_eq!(
        seen.writes_under_question, 0,
        "the expiry under the question writes nothing to the pty"
    );
    assert!(
        seen.armed_at_answer,
        "the give-up is armed afresh at the answer"
    );
    assert!(
        seen.failed_after_answer,
        "a bootstrap that never completes after the answer is still judged"
    );
}

/// #2127, the kill switch (`PHOSPHOR_BOOTSTRAP_GIVE_UP_PAUSED_BY_HELPER_QUESTION=0`): the clock
/// runs through the question as it did before, so the expiry under the question judges the
/// session failed. This is also the control of the test above: the same scenario does show the
/// failure when the pause is off.
#[test]
fn bootstrap_give_up_runs_through_the_helper_question_with_the_kill_switch() {
    let seen = bootstrap_give_up_under_the_helper_question(false);
    assert!(!seen.paused_under_question);
    assert!(
        seen.failed_under_question,
        "switch off: the give-up judges the session while the question is up, as before #2127"
    );
    assert!(
        !seen.armed_at_answer,
        "switch off: the answer arms nothing (the session was judged once)"
    );
}

#[test]
fn helper_question_pause_rule() {
    let asked = SessionId::from(2127);
    let other = SessionId::from(2128);
    assert!(helper_question_pauses_bootstrap_give_up(
        true,
        asked,
        Some(asked),
        None
    ));
    // The kill switch.
    assert!(!helper_question_pauses_bootstrap_give_up(
        false,
        asked,
        Some(asked),
        None
    ));
    // The armed give-up belongs to another pending session, or to none.
    assert!(!helper_question_pauses_bootstrap_give_up(
        true,
        asked,
        Some(other),
        None
    ));
    assert!(!helper_question_pauses_bootstrap_give_up(
        true, asked, None, None
    ));
    // Already judged: a setup is judged once.
    assert!(!helper_question_pauses_bootstrap_give_up(
        true,
        asked,
        Some(asked),
        Some(asked)
    ));
    assert!(bootstrap_give_up_paused_by_helper_question_from(None));
    assert!(bootstrap_give_up_paused_by_helper_question_from(Some("1")));
    assert!(!bootstrap_give_up_paused_by_helper_question_from(Some(
        " 0 "
    )));
}

use crate::terminal::event::RemoteServerSetupState;

/// What [`bootstrap_give_up_under_the_helper_install`] saw.
struct HelperInstallGiveUp {
    /// The install's start took the give-up off the clock.
    paused_during_install: bool,
    /// The session was judged failed by the give-up that expired while the app installed.
    failed_during_install: bool,
    /// pty writes made by that expiry.
    writes_during_install: usize,
    /// A give-up was armed afresh when the install reported.
    armed_at_install_end: bool,
    /// That one, expiring with no `Bootstrapped`, judged the session failed.
    failed_after_install: bool,
}

/// #2135: an ssh session whose remote shell sent `InitShell`, with a line typed during the
/// connect held and the give-up armed as the `SSH` hook arms it. The app then starts to install
/// the remote helper (the answer "Install", or a stored `allow` for the host): the setup state
/// becomes `Installing`, with a progress update after it. The give-up armed before the install
/// expires while it runs (an upload takes longer than 7 s), the install reports, and the
/// give-up that is current after that expires too.
fn bootstrap_give_up_under_the_helper_install(switch_on: bool) -> HelperInstallGiveUp {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_all_pty_writes(&mut app, &terminal);
        let remote_session = SessionId::from(167303092612202);
        let armed_before_install = terminal.update(&mut app, |view, ctx| {
            view.bootstrap_give_up_pauses_for_helper_question = switch_on;
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            assert_eq!(
                view.model.lock().pending_session_id(),
                Some(remote_session),
                "precondition: the remote session is the pending one"
            );
            // What `ModelEvent::SSH` does for a bash remote.
            view.start_bootstrap_timer(BOOTSTRAP_FAILED_DURATION, ctx);
            let arm = BootstrapTimerArm {
                generation: view.bootstrap_timer_generation,
                session: Some(remote_session),
            };
            // What `RemoteServerManagerEvent::SetupStateChanged` does when the install starts,
            // and again for a progress update.
            view.on_remote_helper_setup_state(
                remote_session,
                &RemoteServerSetupState::Installing {
                    progress_percent: None,
                },
                ctx,
            );
            view.on_remote_helper_setup_state(
                remote_session,
                &RemoteServerSetupState::Installing {
                    progress_percent: Some(40),
                },
                ctx,
            );
            arm
        });
        let writes_before = pty_writes.borrow().len();
        // 7 s pass with the install still running.
        let (failed_during_install, paused_during_install, generation_during_install) = terminal
            .update(&mut app, |view, ctx| {
                view.on_bootstrap_timer_fired(armed_before_install, ctx);
                (
                    view.ssh_bootstrap_failed_session == Some(remote_session),
                    view.bootstrap_give_up_paused_for_helper_install == Some(remote_session),
                    view.bootstrap_timer_generation,
                )
            });
        let writes_during_install = pty_writes.borrow().len() - writes_before;
        // What `RemoteServerManagerEvent::BinaryInstallComplete` does.
        let (armed_at_install_end, failed_after_install) =
            terminal.update(&mut app, |view, ctx| {
                view.on_remote_helper_install_finished(remote_session, ctx);
                assert_eq!(
                    view.bootstrap_give_up_paused_for_helper_install, None,
                    "a pause never outlives its install"
                );
                let armed_at_install_end =
                    view.bootstrap_timer_generation != generation_during_install;
                // No `Bootstrapped` follows: the give-up that is current now expires.
                let arm = BootstrapTimerArm {
                    generation: view.bootstrap_timer_generation,
                    session: view.model.lock().pending_session_id(),
                };
                view.on_bootstrap_timer_fired(arm, ctx);
                (
                    armed_at_install_end,
                    view.ssh_bootstrap_failed_session == Some(remote_session),
                )
            });
        HelperInstallGiveUp {
            paused_during_install,
            failed_during_install,
            writes_during_install,
            armed_at_install_end,
            failed_after_install,
        }
    })
}

/// #2135: while the app itself installs the remote helper the bootstrap has not been written,
/// so a give-up that expires then judges nothing: the session is not marked failed and not a
/// byte is written to the pty (before #2135 a slow install was judged a failed bootstrap: the
/// held line was written to the remote shell's raw, unbootstrapped prompt). The install's
/// report arms the give-up afresh, and it still judges a bootstrap that then never comes.
#[test]
fn bootstrap_give_up_does_not_judge_a_session_while_the_app_installs_the_helper() {
    let seen = bootstrap_give_up_under_the_helper_install(true);
    assert!(
        seen.paused_during_install,
        "the install's start takes the give-up off the clock"
    );
    assert!(
        !seen.failed_during_install,
        "a session the app is installing the helper for is not a failed bootstrap"
    );
    assert_eq!(
        seen.writes_during_install, 0,
        "the expiry during the install writes nothing to the pty"
    );
    assert!(
        seen.armed_at_install_end,
        "the give-up is armed afresh when the install reports"
    );
    assert!(
        seen.failed_after_install,
        "a bootstrap that never completes after the install is still judged"
    );
}

/// #2135, the kill switch (shared with #2127): the clock runs through the install as it did
/// before, so the expiry during the install judges the session failed. Also the control of the
/// test above: the same scenario does show the failure when the pause is off.
#[test]
fn bootstrap_give_up_runs_through_the_helper_install_with_the_kill_switch() {
    let seen = bootstrap_give_up_under_the_helper_install(false);
    assert!(!seen.paused_during_install);
    assert!(
        seen.failed_during_install,
        "switch off: the give-up judges the session while the app installs, as before #2135"
    );
    assert!(
        !seen.armed_at_install_end,
        "switch off: the install's report arms nothing (the session was judged once)"
    );
}

/// #2135: while the install pause is set for the pending session no give-up is armed by any
/// other caller, and only the install and update states are an install.
#[test]
fn bootstrap_give_up_is_not_armed_while_the_app_installs_the_helper() {
    assert!(setup_state_is_helper_install(
        &RemoteServerSetupState::Installing {
            progress_percent: None
        }
    ));
    assert!(setup_state_is_helper_install(
        &RemoteServerSetupState::Updating
    ));
    assert!(!setup_state_is_helper_install(
        &RemoteServerSetupState::Checking
    ));
    assert!(!setup_state_is_helper_install(
        &RemoteServerSetupState::Initializing
    ));
    assert!(!setup_state_is_helper_install(
        &RemoteServerSetupState::Ready
    ));
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let remote_session = SessionId::from(167303092612202);
        terminal.update(&mut app, |view, ctx| {
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            view.on_remote_helper_setup_state(
                remote_session,
                &RemoteServerSetupState::Updating,
                ctx,
            );
            assert_eq!(
                view.bootstrap_give_up_paused_for_helper_install,
                Some(remote_session)
            );
            // An arm from anywhere else supersedes earlier timers but arms none.
            view.start_bootstrap_timer(BOOTSTRAP_FAILED_DURATION, ctx);
            assert_eq!(
                view.bootstrap_give_up_paused_for_helper_install,
                Some(remote_session),
                "the pause stays until the install reports"
            );
            // The report of another session's install changes nothing here.
            view.on_remote_helper_install_finished(SessionId::from(2135), ctx);
            assert_eq!(
                view.bootstrap_give_up_paused_for_helper_install,
                Some(remote_session)
            );
        });
    })
}

/// What [`interrupt_at_the_helper_question`] saw.
struct HelperQuestionInterrupt {
    /// SIGINTs sent to the pty's foreground group (the ssh client).
    sigints: usize,
    /// Sessions whose question the controller was told is abandoned.
    abandoned: Vec<SessionId>,
    /// The question is still on screen.
    question_showing: bool,
    /// The line typed during the connect is still held.
    still_holding: bool,
    /// The "interrupt held" notice was shown for the session.
    held_notice: bool,
    /// Bytes written to the pty.
    pty_writes: usize,
}

/// The two ways an interrupt key reaches the view.
#[derive(Clone, Copy)]
enum InterruptPath {
    /// The cancel binding: `ctrl_c` ends in `ctrl_c_to_active_block` (the ssh block is long
    /// running, no agent in control).
    Binding,
    /// The key as an arrival of the input table (row P1a).
    Arrival,
}

/// #2134: an ssh session whose remote shell sent `InitShell`, a line typed during the connect
/// held, the app's "install the remote helper?" question on screen, and then `key` (Ctrl-C or
/// Ctrl-D) by `path`.
fn interrupt_at_the_helper_question(
    switch_on: bool,
    path: InterruptPath,
    key: &'static str,
) -> HelperQuestionInterrupt {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_all_pty_writes(&mut app, &terminal);
        let sigints = Rc::new(RefCell::new(0usize));
        let abandoned: Rc<RefCell<Vec<SessionId>>> = Rc::new(RefCell::new(Vec::new()));
        let (sigint_counter, abandoned_log) = (sigints.clone(), abandoned.clone());
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| match event {
                Event::SigintForegroundToPty => *sigint_counter.borrow_mut() += 1,
                Event::RemoteServerQuestionAbandoned { session_id } => {
                    abandoned_log.borrow_mut().push(*session_id);
                }
                _ => {}
            });
        });
        let remote_session = SessionId::from(167303092612202);
        let (question_showing, still_holding, held_notice) =
            terminal.update(&mut app, |view, ctx| {
                view.helper_question_interrupt_ends_ssh = switch_on;
                ssh_pane_with_held_typeahead_for_test(view, ctx);
                view.start_bootstrap_timer(BOOTSTRAP_FAILED_DURATION, ctx);
                view.show_ssh_remote_server_choice_block(remote_session, ctx);
                assert!(view.ssh_helper_question_showing());
                assert_eq!(
                    view.ssh_bootstrap_interrupt_route(),
                    Some(SshBootstrapInterruptRoute::Hold),
                    "precondition: the bootstrap route holds an interrupt"
                );
                match path {
                    InterruptPath::Binding => {
                        assert_eq!(key, "\u{3}", "the binding is the interrupt key");
                        view.ctrl_c_to_active_block(true, false, None, ctx);
                    }
                    InterruptPath::Arrival => view.keydown_on_terminal(key, ctx),
                }
                (
                    view.ssh_helper_question_showing(),
                    view.ssh_typeahead_holding,
                    view.ssh_interrupt_held_notified == Some(remote_session),
                )
            });
        let sigints = *sigints.borrow();
        let abandoned = abandoned.borrow().clone();
        let pty_writes = pty_writes.borrow().len();
        HelperQuestionInterrupt {
            sigints,
            abandoned,
            question_showing,
            still_holding,
            held_notice,
            pty_writes,
        }
    })
}

/// #2134 (owner decision 2026-11-11): Ctrl-C while the remote-helper question is showing ends
/// the ssh, by either path the key takes. The question is dismissed, the controller is told to
/// drop the bootstrap it held, the ssh client gets SIGINT (its tty is raw: a ^C byte would go to
/// the remote shell), the line typed during the connect is void and nothing is written to the
/// pty. Before #2134 the key was held with a notice for as long as the question was up.
#[test]
fn ctrl_c_at_the_helper_question_ends_the_ssh() {
    let remote_session = SessionId::from(167303092612202);
    for path in [InterruptPath::Binding, InterruptPath::Arrival] {
        let seen = interrupt_at_the_helper_question(true, path, "\u{3}");
        assert_eq!(seen.sigints, 1, "one SIGINT for the ssh client");
        assert_eq!(
            seen.abandoned,
            vec![remote_session],
            "the controller drops the held bootstrap of that session"
        );
        assert!(!seen.question_showing, "the question is dismissed");
        assert!(!seen.still_holding, "what was typed before is void");
        assert!(!seen.held_notice, "the interrupt was not held");
        assert_eq!(seen.pty_writes, 0, "no byte for the remote shell");
    }
}

/// #2134, the kill switch (`PHOSPHOR_HELPER_QUESTION_INTERRUPT_ENDS_SSH=0`) and the control of
/// the test above: the interrupt takes the bootstrap route as before, held with its notice, and
/// the question stays.
#[test]
fn ctrl_c_at_the_helper_question_is_held_with_the_kill_switch() {
    for path in [InterruptPath::Binding, InterruptPath::Arrival] {
        let seen = interrupt_at_the_helper_question(false, path, "\u{3}");
        assert_eq!(seen.sigints, 0);
        assert!(seen.abandoned.is_empty());
        assert!(seen.question_showing, "the question stays");
        assert!(seen.still_holding, "the held line stays held");
        assert!(seen.held_notice, "held with the notice, as before #2134");
        assert_eq!(seen.pty_writes, 0);
    }
}

/// #2134 decides the interrupt key only: a Ctrl-D at the question stays held, the question
/// stays, nothing is abandoned.
#[test]
fn ctrl_d_at_the_helper_question_stays_held() {
    let seen = interrupt_at_the_helper_question(true, InterruptPath::Arrival, "\u{4}");
    assert_eq!(seen.sigints, 0);
    assert!(seen.abandoned.is_empty());
    assert!(seen.question_showing);
    assert!(seen.still_holding);
    assert_eq!(seen.pty_writes, 0);
}

#[test]
fn helper_question_interrupt_rule() {
    use SshBootstrapInterruptRoute::{Forward, Hold};
    let asked = SessionId::from(2134);
    let other = SessionId::from(2135);
    assert!(helper_question_interrupt_ends_ssh(
        true,
        Some(Hold),
        Some(asked),
        Some(asked)
    ));
    // Whatever the bootstrap route says, while the question of the pending session is up.
    assert!(helper_question_interrupt_ends_ssh(
        true,
        Some(Forward),
        Some(asked),
        Some(asked)
    ));
    // The kill switch.
    assert!(!helper_question_interrupt_ends_ssh(
        false,
        Some(Hold),
        Some(asked),
        Some(asked)
    ));
    // No question on screen: the bootstrap route decides.
    assert!(!helper_question_interrupt_ends_ssh(
        true,
        Some(Hold),
        None,
        Some(asked)
    ));
    // The question of an abandoned connect, or no pending session at all.
    assert!(!helper_question_interrupt_ends_ssh(
        true,
        Some(Hold),
        Some(asked),
        Some(other)
    ));
    assert!(!helper_question_interrupt_ends_ssh(
        true,
        None,
        Some(asked),
        None
    ));
    // No ssh-style bootstrap pending (a subshell, or already bootstrapped).
    assert!(!helper_question_interrupt_ends_ssh(
        true,
        None,
        Some(asked),
        Some(asked)
    ));
    assert!(helper_question_interrupt_ends_ssh_from(None));
    assert!(helper_question_interrupt_ends_ssh_from(Some("1")));
    assert!(!helper_question_interrupt_ends_ssh_from(Some(" 0 ")));
}

/// #1566: the deferral is one grace, not an escape hatch: if `Bootstrapped` never comes, the
/// second expiry fails the session and writes the held keys to the pty in typed order, with no
/// `stty sane` (owner decision 2026-11-09, #1996; under #1577 this test expected the held text
/// handed back and nothing at the pty).
#[test]
fn ssh_bootstrap_timer_second_expiry_after_the_grace_still_fails_the_session() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        // The hand-over writes through the counted route too (`WriteHandoffUserBytesToPty`).
        let pty_writes = record_all_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            view.model
                .lock()
                .process_bytes("stty -echo; eval \"$(cat)\"\r\n");
            view.model
                .lock()
                .block_list()
                .active_block()
                .interactive_latch()
                .force(true);
            assert!(view.is_long_running(), "the bootstrap block is running");
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            view.on_bootstrap_failed_timer_complete((), ctx);
            assert!(view.ssh_typeahead_holding);
            view.on_bootstrap_failed_timer_complete((), ctx);
            assert!(!view.ssh_typeahead_holding);
            assert!(view.ssh_held_is_empty());
            let input = view.input.as_ref(ctx);
            assert!(
                input.handed_back_text_for_test().is_none() && input.buffer_text(ctx).is_empty(),
                "the held text went to the pty, not back to the editor"
            );
        });
        assert_eq!(
            String::from_utf8_lossy(&pty_writes.borrow().concat()),
            "echo hi\r",
            "the held keys in typed order, once; no `stty sane`"
        );
    })
}

/// #1494: if the shell is gone when the bootstrap timer fires, nothing can read the held keys
/// from the pty and nothing is run. They come back to the pane's input as text, in typed order,
/// with the hand-back's Enter guard armed: visible, never discarded, never written, never kept
/// out of sight for a block that will not end.
///
/// Expectation history (owner decision 2026-11-09, a changed decision and not a weakening): as
/// `ssh_bootstrap_failure_with_a_dead_shell_discards_the_held_typeahead` this test expected the
/// input EMPTY, i.e. the held `echo hi` + Enter discarded with a log line. It was the last drop
/// on the give-up paths (#1996). What it still asserts unchanged: the hold is over, nothing
/// reaches the pty.
#[test]
fn ssh_bootstrap_failure_with_a_dead_shell_hands_the_held_typeahead_back_as_guarded_text() {
    App::test((), move |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        let executed = count_executed_commands(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            ssh_pane_with_held_typeahead_for_test(view, ctx);
            view.model
                .lock()
                .exit(crate::terminal::model::terminal_model::ExitReason::ShellProcessExited);
        });
        let executed_before = *executed.borrow();
        terminal.update(&mut app, |view, ctx| {
            view.on_bootstrap_failed_timer_complete((), ctx);
            assert!(!view.ssh_typeahead_holding, "the hold is over");
            assert!(view.ssh_held_is_empty());
            let input = view.input.as_ref(ctx);
            assert_eq!(
                input.buffer_text(ctx),
                "echo hi",
                "the held keys are in the input as text, in typed order"
            );
            assert!(
                input.ssh_handover_enter_guard_armed(),
                "the first Enter on the handed-back text is held"
            );
            assert!(
                input.handed_back_text_for_test().is_none(),
                "not stashed for a block that will never end"
            );
        });
        assert!(
            pty_writes.borrow().is_empty(),
            "nothing is written to a dead shell: {:?}",
            pty_writes.borrow()
        );
        assert_eq!(*executed.borrow(), executed_before, "nothing is run");
        // A second expiry finds nothing held and changes nothing.
        terminal.update(&mut app, |view, ctx| {
            view.on_bootstrap_failed_timer_complete((), ctx);
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "echo hi");
        });
        assert!(pty_writes.borrow().is_empty());
    });
}

/// #1085 (#983 window 5): the remote session is announced and finishes bootstrapping
/// (`Bootstrapped`), but its shell is not at its prompt yet: the bootstrap script, MOTD and rc
/// files are still finishing in a running block. Keys typed there used to be written to the tty
/// (the gate released at `Bootstrapped`), reached the remote line editor as typeahead, and came
/// back at the prompt merged with the keys the editor took meanwhile: `echo TY$((20+1))-$(uname
/// -n)` ran as `ech TY$((20+1))-$()uname -n)`, and a stray `)` stayed in the remote line to
/// prefix the next command. The line must be dropped whole, its tail and Enter included, even
/// after the first prompt released the gate; the next line passes.
/// Not compiled/run when written (no builds in the fix pass).
#[test]
fn ssh_keys_between_bootstrapped_and_first_remote_prompt_are_dropped_whole() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        let remote_session = SessionId::from(167303092612202);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            submit_command(view, "ssh host", ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "");
            // The ssh block, captured before the remote shell's InitShell can start another.
            let armed = view.model.lock().active_block_id().clone();
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            simulate_ssh_hook(view);
            view.refresh_ssh_connect_gate();
            // The model events (the ssh hook, InitShell) feed the edge-driven phase in `table`
            // mode; the test calls the gate directly, so it feeds what the events would.
            view.ssh_observe(ctx);
            // The remote shell announces itself (pending session); the gate sees it.
            view.model.lock().init_shell(InitShellValue {
                pid: None,
                session_id: remote_session,
                shell: "bash".to_owned(),
                user: "user".to_owned(),
                hostname: "host".to_owned(),
                ..Default::default()
            });
            assert!(view.refresh_ssh_connect_gate());
            view.ssh_observe(ctx);
            assert!(
                view.ssh_connect_gate
                    .as_ref()
                    .is_some_and(|g| g.saw_pending)
            );
            // The ssh block ends cleanly at the bootstrap's own precmd.
            view.apply_block_completed_to_ssh_gate(&armed, 0);
            view.warpify_state.clear_pending_ssh_host();
            // That precmd is handled while the session is still pending: not the first prompt.
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            // The bootstrap finishes; its prompt has not been drawn yet.
            view.model.lock().bootstrapped(BootstrappedValue {
                shell: "bash".to_owned(),
                ..Default::default()
            });
            view.handle_terminal_event(
                &ModelEvent::Handler(AnsiHandlerEvent::Bootstrapped {
                    session_id: remote_session,
                    is_subshell: false,
                }),
                ctx,
            );
            assert!(
                view.ssh_connect_gate.is_some(),
                "Bootstrapped is not the remote prompt: the gate must still hold"
            );
            view.typed_characters_on_terminal("ec", ctx);
            assert!(view.ssh_typeahead_holding, "held, not dropped");
            assert_eq!(
                view.input.as_ref(ctx).buffer_text(ctx),
                "",
                "held text must not land in the editor"
            );
            view.typed_characters_on_terminal("ho TY$((20+1))-$(uname -n)", ctx);
            view.keydown_on_terminal("\r", ctx);
            assert!(view.ssh_typeahead_holding);
            // Fixed setup: a command runs in the foreground, so the keys that are delivered go
            // to the pty, where the assertions below can read them.
            view.model.lock().simulate_long_running_block("sleep 5", "");
            // The remote shell's first prompt: the gate hands input over, and the held keys are
            // delivered in the handling of that same event (#1348), not later.
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            assert!(
                view.ssh_connect_gate.is_none(),
                "the first remote prompt releases the gate"
            );
            assert!(view.ssh_remote_prompt_seen);
            assert!(!view.ssh_typeahead_holding);
            assert!(view.ssh_held_is_empty());
        });
        let writes = pty_writes.borrow();
        let delivered = String::from_utf8_lossy(&writes.concat()).into_owned();
        assert!(
            delivered.contains("echo TY$((20+1))-$(uname -n)\r"),
            "the line must arrive whole and in order, Enter last: {delivered:?}"
        );
    })
}

