/// #1111: Ctrl-D while the ssh connect is still silent (before the remote announces itself) is
/// held, not written: written there it left an unmanaged remote shell behind (bash) or fed the
/// remote bootstrap to the local shell (fish). The same through the `ctrl_d` action. Once
/// the connect prints something (a password prompt) Ctrl-D reaches ssh again.
#[test]
fn ssh_ctrl_d_is_held_during_a_silent_connect() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            submit_command(view, "ssh host", ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "");
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            view.keydown_on_terminal("\u{4}", ctx);
            view.typed_characters_on_terminal("\u{4}", ctx);
            view.ctrl_d(ctx);
        });
        assert!(
            !pty_writes.borrow().iter().any(|w| w.as_slice() == b"\x04"),
            "{:?}",
            pty_writes.borrow()
        );
        terminal.update(&mut app, |view, ctx| {
            // ssh owns the tty and asks something (an unterminated line, #1111's own test).
            ssh_tty_owned_for_test(view, ctx);
            view.model.lock().process_bytes("Password: ");
            view.keydown_on_terminal("\u{4}", ctx);
            // The EOT that passes while the gate is armed must not make the app ignore the
            // remote's hooks (that left an unmanaged remote shell behind).
            assert!(!view.model.lock().is_ignoring_bootstrapping_messages());
        });
        assert!(
            pty_writes.borrow().iter().any(|w| w.as_slice() == b"\x04"),
            "Ctrl-D must still cancel a visible prompt: {:?}",
            pty_writes.borrow()
        );
    })
}

/// #1111: after a password prompt was answered and before the ssh hook, the connect is silent
/// again; Ctrl-D there is held too (the gate's `tty_owned` stays set, so the key drop alone
/// would let it through).
#[test]
fn ssh_ctrl_d_is_held_after_a_prompt_was_answered() {
    App::test((), |mut app| async move {
        // Ran on the legacy path only (r18cz pinned it there while the gate's `tty_owned` was
        // still latched by a key); since #1353 step 8 the table decides it. The ownership is the
        // event's (`ssh_tty_owned_for_test`), the ^D is held by row P1a (`ssh_eot_must_wait`). The
        // machine's own statement of the rule is `ssh_phase_tests::ownership_is_sticky_for_the_window`.
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            submit_command(view, "ssh host", ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "");
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            ssh_tty_owned_for_test(view, ctx);
            view.model.lock().process_bytes("Password: ");
            view.keydown_on_terminal("\r", ctx);
            assert!(view.ssh_connect_gate.as_ref().is_some_and(|g| g.tty_owned));
            view.model.lock().process_bytes("\r\n");
            view.keydown_on_terminal("\u{4}", ctx);
            view.ctrl_d(ctx);
        });
        assert!(
            !pty_writes.borrow().iter().any(|w| w.as_slice() == b"\x04"),
            "{:?}",
            pty_writes.borrow()
        );
    })
}

