/// #1292: the held keys keep their order and exact content, and the unexecuted fallback text
/// follows the user's edits.
#[test]
fn ssh_held_keys_keep_order_and_fallback_text_follows_edits() {
    let mut held = crate::terminal::view::ssh_typeahead::SshTypeahead::default();
    for key in ["echo", " ", "secrex", "\u{7f}", "t"] {
        held.push(HeldInput::from_chars(key));
    }
    assert_eq!(held.unexecuted_text(), "echo secret");
    held.push(HeldInput::from_chars("\u{17}"));
    assert_eq!(held.unexecuted_text(), "echo ");
    held.push(HeldInput::from_chars("\u{15}"));
    assert_eq!(held.unexecuted_text(), "");
}

/// #1113 / #1292: held text is never concatenated with what the editor holds. With an empty
/// editor it is shown; with a non-empty one it used to be DISCARDED (lost keys, #1571 review): it
/// now goes on a line of its own after that text, never glued into it, the Enter guard armed.
#[test]
fn ssh_held_line_is_never_glued_to_existing_editor_text() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            view.ssh_remote_prompt_seen = false;
            view.input
                .update(ctx, |input, ctx| input.replace_buffer_content("world", ctx));
            view.ssh_typeahead_holding = true;
            view.ssh_hold_push(HeldInput::from_chars("hello "), ctx);
            view.finish_ssh_typeahead(ctx);
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "world\nhello ");
            assert!(view.input.as_ref(ctx).ssh_handover_enter_guard_armed());
            assert!(view.ssh_held_is_empty());
            view.input.update(ctx, |input, ctx| {
                input.clear_buffer_and_reset_undo_stack(ctx)
            });
            view.ssh_typeahead_holding = true;
            view.ssh_hold_push(HeldInput::from_chars("hello"), ctx);
            view.ssh_hold_push(HeldInput::from_chars("\r"), ctx);
            view.finish_ssh_typeahead(ctx);
            assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "hello");
        });
    })
}

/// #1115 / #1292: a line whose letters were held and whose Enter arrives just after the gate
/// release is held with its letters: the Enter is never delivered alone, and nothing is run
/// before the remote shell's prompt has delivered the whole line.
#[test]
fn ssh_enter_just_after_release_stays_with_its_held_letters() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        let executed: Rc<RefCell<Vec<String>>> = Rc::new(RefCell::new(Vec::new()));
        let sink = executed.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if let Event::ExecuteCommand(e) = event {
                    sink.borrow_mut().push(e.command.clone());
                }
            });
        });
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            submit_command(view, "ssh host", ctx);
            for key in ["e", "x", "i", "t"] {
                view.typed_characters_on_terminal(key, ctx);
            }
            assert!(view.ssh_typeahead_holding);
            // The remote's first prompt releases the gate between the letters and the Enter.
            let gate = view.ssh_connect_gate.as_mut().unwrap();
            gate.saw_pending = true;
            gate.bootstrap_done_at = Some(Instant::now());
            view.handle_terminal_event(&ModelEvent::Handler(AnsiHandlerEvent::Precmd), ctx);
            assert!(view.ssh_connect_gate.is_none());
            view.keydown_on_terminal("\r", ctx);
            assert_eq!(
                view.ssh_hold_take(),
                vec![
                    HeldInput::Typed("exit".to_owned()),
                    HeldInput::Key("\r".to_owned())
                ],
                "the Enter stays with its letters"
            );
        });
        assert_eq!(executed.borrow().as_slice(), ["ssh host".to_owned()]);
        assert!(pty_writes.borrow().is_empty(), "{:?}", pty_writes.borrow());
    })
}

/// #1111 regression: with NO ssh connect pending, Ctrl-D is never held -- a local shell whose
/// rc file waits on `read` during bootstrap needs the EOT to reach the pty.
#[test]
fn ctrl_d_is_written_during_local_bootstrapping_without_an_ssh_connect() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = collect_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            // A local program (an rc file's `read`) is blocked on stdin: a running block, the
            // editor hidden, so Ctrl-D is the EOF that ends it. No ssh command was submitted.
            view.model
                .lock()
                .simulate_long_running_block("python3 -c 'input()'", "");
            assert!(view.ssh_connect_gate.is_none());
            assert!(!view.ssh_connect_holds_eot());
            view.ctrl_d(ctx);
        });
        assert!(
            pty_writes.borrow().iter().any(|w| w.as_slice() == b"\x04"),
            "ctrl_d must write the EOT: {:?}",
            pty_writes.borrow()
        );
        pty_writes.borrow_mut().clear();
        terminal.update(&mut app, |view, ctx| {
            view.keydown_on_terminal("\u{4}", ctx);
        });
        assert!(
            pty_writes.borrow().iter().any(|w| w.as_slice() == b"\x04"),
            "keydown must write the EOT: {:?}",
            pty_writes.borrow()
        );
    })
}

/// #1124: the input editor's Ctrl-D (InputEvent::CtrlD) in the first-prompt window after the
/// remote's Bootstrapped hook must be held, not turned into an EOT write plus a started
/// command (which left a phantom running block); with no ssh connect it still goes through.
#[test]
fn editor_ctrl_d_is_held_in_the_ssh_first_prompt_window() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let ctrl_ds = Rc::new(RefCell::new(0usize));
        let counter = ctrl_ds.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if matches!(event, Event::CtrlD) {
                    *counter.borrow_mut() += 1;
                }
            });
        });
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            // No ssh connect: the editor's Ctrl-D goes through as before.
            view.handle_input_event(&InputEvent::CtrlD, ctx);
        });
        assert_eq!(*ctrl_ds.borrow(), 1);
        terminal.update(&mut app, |view, ctx| {
            submit_command(view, "ssh host", ctx);
            // The remote announced itself and finished bootstrapping; its prompt is pending.
            let gate = view.ssh_connect_gate.as_mut().unwrap();
            gate.saw_pending = true;
            gate.managed = true;
            gate.bootstrap_done_at = Some(Instant::now());
            view.handle_input_event(&InputEvent::CtrlD, ctx);
        });
        assert_eq!(*ctrl_ds.borrow(), 1, "held: no EOT write, no started block");
    })
}

/// #1125: a line the user submitted that the controller did NOT start (a command already
/// running / waiting, a terminated session) used to vanish: the editor was already cleared and
/// nothing was written. It is given back to the editor (an empty one only) with a toast.
#[test]
fn a_user_command_that_was_not_started_is_given_back_to_the_editor() {
    use crate::terminal::model::lifecycle::StartCommandOutcome;
    use crate::terminal::writeable_pty::terminal_manager_util::handle_command_not_run;
    for outcome in [
        StartCommandOutcome::RejectedExecuting,
        StartCommandOutcome::Coalesced,
        StartCommandOutcome::IgnoredTerminated,
    ] {
        App::test((), |mut app| async move {
            initialize_app_for_terminal_view(&mut app);
            app.add_singleton_model(|_| crate::workspace::ToastStack);
            let terminal = add_window_with_terminal(&mut app, None);
            let event = ExecuteCommandEvent {
                command: "exit".to_owned(),
                session_id: SessionId::from(9001),
                workflow_id: None,
                workflow_command: None,
                should_add_command_to_history: true,
                source: CommandExecutionSource::User,
            };
            let weak = terminal.downgrade();
            app.update(|ctx| handle_command_not_run(&weak, &event, outcome, ctx));
            terminal.read(&app, |view, ctx| {
                assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "exit");
            });
            // Text typed since is never overwritten.
            terminal.update(&mut app, |view, ctx| {
                view.input
                    .update(ctx, |input, ctx| input.replace_buffer_content("ls", ctx));
            });
            app.update(|ctx| handle_command_not_run(&weak, &event, outcome, ctx));
            terminal.read(&app, |view, ctx| {
                assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "ls");
            });
            // An accepted start restores nothing.
            terminal.update(&mut app, |view, ctx| {
                view.input.update(ctx, |input, ctx| {
                    input.clear_buffer_and_reset_undo_stack(ctx)
                });
            });
            app.update(|ctx| {
                handle_command_not_run(&weak, &event, StartCommandOutcome::Accepted, ctx)
            });
            terminal.read(&app, |view, ctx| {
                assert_eq!(view.input.as_ref(ctx).buffer_text(ctx), "");
            });
        });
    }
}

fn record_pty_writes(
    app: &mut App,
    terminal: &ViewHandle<TerminalView>,
) -> Rc<RefCell<Vec<Vec<u8>>>> {
    let pty_writes: Rc<RefCell<Vec<Vec<u8>>>> = Rc::new(RefCell::new(Vec::new()));
    let writes = pty_writes.clone();
    app.update(|ctx| {
        ctx.subscribe_to_view(terminal, move |_, event, _| {
            if let Event::WriteBytesToPty { bytes } = event {
                writes.borrow_mut().push(bytes.to_vec());
            }
        });
    });
    pty_writes
}

/// Like [`record_pty_writes`], but also records the writes the typeahead hand-off counts
/// (`Event::WriteHandoffUserBytesToPty`): both reach the pty, and right after an ssh hand-over the
/// counted route is the expected one.
fn record_all_pty_writes(
    app: &mut App,
    terminal: &ViewHandle<TerminalView>,
) -> Rc<RefCell<Vec<Vec<u8>>>> {
    let pty_writes: Rc<RefCell<Vec<Vec<u8>>>> = Rc::new(RefCell::new(Vec::new()));
    let writes = pty_writes.clone();
    app.update(|ctx| {
        ctx.subscribe_to_view(terminal, move |_, event, _| match event {
            Event::WriteBytesToPty { bytes } | Event::WriteHandoffUserBytesToPty { bytes } => {
                writes.borrow_mut().push(bytes.to_vec());
            }
            _ => {}
        });
    });
    pty_writes
}

/// Registers the local shell session the way a bootstrapped pane has it. Typed text only goes to
/// the pty (rather than the input editor) once a session exists, as it does for a real ssh run.
fn register_local_session_for_ssh_test(view: &TerminalView, ctx: &mut ViewContext<TerminalView>) {
    use crate::terminal::model::session::SessionInfo;

    view.sessions.update(ctx, |sessions, _| {
        sessions
            .register_session_for_test(SessionInfo::new_for_test().with_id(SessionId::from(9001)));
    });
}

/// What the remote shell's first Precmd leaves behind (#1332): its session is registered with the
/// history model (the Bootstrapped hook) and the active block carries the session id (the Precmd).
/// Until then the session refuses a command (`HistoryNotAppendable`) and held ssh keys wait.
fn first_precmd_processed_for_test(view: &TerminalView, ctx: &mut ViewContext<TerminalView>) {
    let session_id = SessionId::from(9001);
    let session = view
        .sessions
        .as_ref(ctx)
        .get(session_id)
        .expect("session registered by register_local_session_for_ssh_test");
    History::handle(ctx).update(ctx, |history, ctx| {
        history.init_session_with(session, async { Vec::new() }, ctx);
    });
    view.model
        .lock()
        .block_list_mut()
        .active_block_for_test()
        .set_session_id(session_id);
}

/// #976: while an ssh command runs with no remote session pending and ssh owns the tty (here
/// asking the host-key question), a plain Enter and typed answers reach the pty.
#[test]
fn ssh_prompt_before_remote_session_receives_enter_and_typed_text() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            view.model.lock().simulate_long_running_block(
                "ssh -o StrictHostKeyChecking=ask host",
                "Are you sure you want to continue connecting (yes/no/[fingerprint])? ",
            );
            view.warpify_state.set_pending_ssh_host(
                "ssh -o StrictHostKeyChecking=ask host".to_owned(),
                Some("host".to_owned()),
            );
            assert!(view.has_pending_ssh_command());
            // The preexec event armed the window; the latch's event says ssh owns the tty.
            view.arm_ssh_connect_gate_at_preexec(ctx);
            assert!(view.ssh_connect_gate.is_some());
            ssh_tty_owned_for_test(view, ctx);
            view.keydown_on_terminal("\r", ctx);
            view.typed_characters_on_terminal("yes", ctx);
            view.keydown_on_terminal("\r", ctx);
        });
        let writes = pty_writes.borrow();
        assert_eq!(
            writes.iter().filter(|w| w.as_slice() == b"\r").count(),
            2,
            "both Enters must reach ssh: {writes:?}"
        );
        assert!(writes.iter().any(|w| w.as_slice() == b"yes"), "{writes:?}");
    })
}

/// #983 / #1292: text typed before ssh owns the tty is held whole (never partly written to the
/// tty); ssh first seen owning it while reading a password discards the held run (the termios
/// guard, as the tty's flush would), and keys flow again from that event.
#[test]
fn ssh_silent_connect_holds_typed_runs_whole_then_ownership_at_a_secret_read_passes_keys() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        // The dropped-typing notice is a toast; the real app always has a toast stack.
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "");
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            view.typed_characters_on_terminal("echo typed-", ctx);
            view.typed_characters_on_terminal("during-connect", ctx);
            view.keydown_on_terminal("\r", ctx);
        });
        assert!(
            pty_writes.borrow().is_empty(),
            "nothing of the typed run may reach the tty: {:?}",
            pty_writes.borrow()
        );
        terminal.update(&mut app, |view, ctx| {
            view.model.lock().process_bytes("host's password: ");
            set_tty_reading_secret_for_test(view, true);
            ssh_tty_owned_for_test(view, ctx);
            view.typed_characters_on_terminal("pw", ctx);
            view.keydown_on_terminal("\r", ctx);
        });
        let writes = pty_writes.borrow();
        assert!(writes.iter().any(|w| w.as_slice() == b"pw"), "{writes:?}");
        assert!(writes.iter().any(|w| w.as_slice() == b"\r"), "{writes:?}");
        assert!(
            !writes
                .iter()
                .any(|w| w.as_slice() == b"echo typed-" || w.as_slice() == b"during-connect"),
            "the blind run never reaches ssh: {writes:?}"
        );
    })
}

/// #983: once ssh owns the tty the gate is open for good, whatever is printed afterwards (a
/// MOTD, a banner ending in a newline): later typing, including a bare Enter, reaches the pty.
#[test]
fn ssh_gate_never_rearms_after_ownership() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "motd\n");
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            view.arm_ssh_connect_gate_at_preexec(ctx);
            ssh_tty_owned_for_test(view, ctx);
            view.typed_characters_on_terminal("cat", ctx);
            view.keydown_on_terminal("\r", ctx);
        });
        {
            let writes = pty_writes.borrow();
            assert!(writes.iter().any(|w| w.as_slice() == b"cat"), "{writes:?}");
            assert!(writes.iter().any(|w| w.as_slice() == b"\r"), "{writes:?}");
        }
        pty_writes.borrow_mut().clear();
        terminal.update(&mut app, |view, ctx| {
            view.model.lock().process_bytes("Banner\n");
            view.keydown_on_terminal("\r", ctx);
        });
        assert!(pty_writes.borrow().iter().any(|w| w.as_slice() == b"\r"));
    })
}

/// #983 / #1292: while ssh is truly silent a paste and control sequences are held like typing;
/// interrupt keys still go through.
#[test]
fn ssh_silent_connect_holds_paste_but_not_interrupts() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        // The dropped-typing notice is a toast; the real app always has a toast stack.
        app.add_singleton_model(|_| crate::workspace::ToastStack);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = record_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            view.model
                .lock()
                .simulate_long_running_block("ssh host", "");
            view.warpify_state
                .set_pending_ssh_host("ssh host".to_owned(), Some("host".to_owned()));
            ctx.clipboard()
                .write(ClipboardContent::plain_text("echo pasted\n".to_owned()));
            view.paste(false, ctx);
        });
        assert!(pty_writes.borrow().is_empty(), "{:?}", pty_writes.borrow());
        terminal.update(&mut app, |view, ctx| {
            view.keydown_on_terminal("\u{1a}", ctx);
            view.keydown_on_terminal("\u{1c}", ctx);
            view.control_sequence_on_terminal(b"\x1b[A", ctx);
            assert_eq!(
                view.ssh_hold_take(),
                vec![HeldInput::Seq("\x1b[A".to_owned())],
                "an arrow key is held with the typing, not written into the bootstrap"
            );
        });
        let writes = pty_writes.borrow();
        for expected in [&b"\x1a"[..], b"\x1c"] {
            assert!(
                writes.iter().any(|w| w.as_slice() == expected),
                "{writes:?}"
            );
        }
        assert!(
            !writes.iter().any(|w| w.as_slice() == b"\x1b[A"),
            "{writes:?}"
        );
    })
}

/// #976: only a choice block of the pending session owns input, wherever it sits in the list.
#[test]
fn only_the_pending_sessions_choice_block_owns_input() {
    let (a, b) = (SessionId::from(1), SessionId::from(2));
    // Stale block A first, current block B second: B is pending.
    assert!(choice_block_owns_input([a, b].into_iter(), Some(b)));
    // Only the stale block exists: nothing owns input.
    assert!(!choice_block_owns_input([a].into_iter(), Some(b)));
    assert!(!choice_block_owns_input([a, b].into_iter(), None));
}

