/// #1430: input synced from another pane does not reach a pane whose hand-over gate is open (here
/// a PowerShell subshell setup): it would land in the bootstrap. Without a gate it is written
/// through the pane's write path and is not reported back to the other panes as typed.
#[test]
fn synced_input_is_held_not_written_into_an_open_hand_over_gate() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let seen = record_pty_door_events(&mut app, &terminal);
        // The view's events reach the recorder when the update returns: each step is its own
        // update and the event assertions read after it.
        terminal.update(&mut app, |view, ctx| {
            register_local_session_for_ssh_test(view, ctx);
            view.model.lock().simulate_long_running_block("claude", "");
            // Control: no gate, the synced bytes are written and the echo guard is consumed.
            view.write_to_pty_for_syncing_long_running_commands(b"ab".to_vec(), ctx);
            assert_eq!(
                view.synced_in_flight, 0,
                "synced bytes are not reported back as typed (that would echo between panes)"
            );
        });
        assert_eq!(
            *seen.borrow(),
            vec![PtyDoorEvent::Bytes(b"ab".to_vec())],
            "synced input reaches a pane running a command"
        );
        seen.borrow_mut().clear();
        terminal.update(&mut app, |view, ctx| {
            announce_powershell_setup(view);
            view.write_to_pty_for_syncing_long_running_commands(b"cd".to_vec(), ctx);
        });
        assert!(
            seen.borrow().is_empty(),
            "nothing synced is written while a PowerShell setup is open: {:?}",
            seen.borrow()
        );
        terminal.update(&mut app, |view, _| {
            assert_eq!(
                powershell_held(view),
                vec![b"cd".to_vec()],
                "it is held in order behind the setup's gate, not dropped"
            );
        });
    })
}

/// #1893 / #1862: whether the input being written is synced is the DELIVERING entry's own origin
/// while the queue delivers, never the enclosing arrival's thread-local: a drain run inside a synced
/// arrival writes the user's own held keys as the user's (they take over an agent program), and a
/// synced entry drained from a pty event stays passive. Not a mode choice: both input paths (legacy
/// writer and table executor) read this one predicate.
#[test]
fn synced_ness_at_delivery_is_the_entrys_not_the_enclosing_arrivals() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, _| {
            // A live arrival: the arrival's origin decides.
            assert!(!view.input_is_synced());
            {
                let _synced = dest_table::set_arrival_origin(input_queue::Origin::Synced);
                assert!(view.input_is_synced());
                // A drain inside the synced arrival delivers the user's own held key.
                view.paste_queue.delivering = true;
                view.paste_queue.delivering_synced = false;
                assert!(
                    !view.input_is_synced(),
                    "a held keyboard entry is not synced because synced text triggered the drain"
                );
                view.paste_queue.delivering = false;
            }
            // A synced entry drained from a pty event (arrival origin is Keyboard).
            view.paste_queue.delivering = true;
            view.paste_queue.delivering_synced = true;
            assert!(view.input_is_synced(), "a held synced entry stays passive");
            view.paste_queue.delivering = false;
            view.paste_queue.delivering_synced = false;
        });
    })
}

/// #1900: synced input that waits in the pane queue is still synced input when it is delivered.
/// Behind an Enter's gate it was offered by the input's own route as a keyboard entry, and for an
/// ssh connect as a keyboard `Held` entry; the delivery reads the entry's origin
/// (`delivering_synced`), so the relay took over an agent-run command in the synced pane. The
/// user's own keys are keyboard entries, as before, and so is everything with the kill switch
/// off (`held_origin_for(_, false)`).
#[test]
fn synced_input_held_in_the_pane_queue_keeps_its_synced_origin() {
    use crate::terminal::input_queue::{GateKind, Origin};
    assert_eq!(dest_table::held_origin_for(true, true), Origin::Synced);
    assert_eq!(dest_table::held_origin_for(false, true), Origin::Keyboard);
    assert_eq!(
        dest_table::held_origin_for(true, false),
        Origin::Keyboard,
        "PHOSPHOR_QUEUE_KEEP_SYNCED_ORIGIN=0"
    );
    assert_eq!(dest_table::held_origin_for(false, false), Origin::Keyboard);

    // Behind an Enter that waits for its verdict.
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes = collect_pty_writes(&mut app, &terminal);
        terminal.update(&mut app, |view, ctx| {
            assert!(
                !view.queue_synced_behind_enter(AfterEnterInput::Text("x".to_owned()), None, ctx),
                "no Enter gate: nothing is queued, the caller goes on"
            );
            let queue = view.paste_queue.queue.clone();
            assert!(queue.borrow().is_idle());
            view.input.update(ctx, |input, ctx| {
                input.open_waiting_enter_gate_for_test(ctx);
                // The user's own key, by the input's route.
                assert!(input.queue_behind_enter(AfterEnterInput::Text("u".to_owned()), ctx));
            });
            assert_eq!(view.held_input_origin(), Origin::Keyboard);
            {
                let _synced = dest_table::set_arrival_origin(Origin::Synced);
                assert_eq!(view.held_input_origin(), Origin::Synced);
                assert!(view.queue_synced_behind_enter(
                    AfterEnterInput::Text("ab".to_owned()),
                    None,
                    ctx
                ));
                assert!(view.queue_synced_behind_enter(AfterEnterInput::Enter, None, ctx));
            }
            let held: Vec<_> = queue
                .borrow()
                .entries()
                .map(|entry| (entry.kind.tag(), entry.kind.len(), entry.origin))
                .collect();
            assert_eq!(
                held,
                vec![
                    ("text", 1, Origin::Keyboard),
                    ("text", 2, Origin::Synced),
                    ("enter", 0, Origin::Synced),
                ],
                "typed order, each with the origin it arrived with"
            );
            assert!(queue.borrow().has_gate_kind(GateKind::EnterVerdict));
        });
        assert!(
            pty_writes.borrow().is_empty(),
            "held, not written: {:?}",
            pty_writes.borrow()
        );
    });

    // Held for an ssh connect.
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            assert_eq!(
                view.ssh_hold_push(HeldInput::Typed("me".to_owned()), ctx),
                SshTypeaheadPush::Held
            );
            {
                let _synced = dest_table::set_arrival_origin(Origin::Synced);
                assert_eq!(
                    view.ssh_hold_push(HeldInput::Typed("them".to_owned()), ctx),
                    SshTypeaheadPush::Held
                );
            }
            let queue = view.paste_queue.queue.clone();
            assert!(queue.borrow().has_gate_kind(GateKind::SshConnect));
            let held: Vec<_> = queue
                .borrow()
                .entries()
                .map(|entry| (entry.kind.tag(), entry.kind.len(), entry.origin))
                .collect();
            assert_eq!(
                held,
                vec![("held", 2, Origin::Keyboard), ("held", 4, Origin::Synced)]
            );
            // Nothing of this test's connect is left for another.
            view.ssh_hold_clear();
            assert!(queue.borrow().is_idle());
        });
    });
}

/// #1431: the agent's pty writes are refused while a subshell / PowerShell setup is in progress
/// (they would land in the bootstrap); outside of one they go out as before.
#[test]
fn agent_pty_writes_are_refused_during_a_subshell_setup() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);
        let seen = record_pty_door_events(&mut app, &terminal);
        // The view's events reach the recorder when the update returns, so each step is its own
        // update and the assertions read after it.
        terminal.update(&mut app, |view, ctx| {
            view.write_agent_bytes_to_pty(b"y\n".to_vec(), &AIAgentPtyWriteMode::Raw, ctx);
        });
        assert_eq!(*seen.borrow(), vec![PtyDoorEvent::Agent(b"y\n".to_vec())]);
        seen.borrow_mut().clear();
        terminal.update(&mut app, |view, ctx| {
            announce_powershell_setup(view);
            view.write_agent_bytes_to_pty(b"q".to_vec(), &AIAgentPtyWriteMode::Raw, ctx);
        });
        assert!(
            seen.borrow().is_empty(),
            "refused while the setup owns the pty: {:?}",
            seen.borrow()
        );
    })
}

